// 📖 آية اليوم — 365 آية قصيرة مختارة (دورة سنة كاملة بلا تكرار)
// النص العربي: quran-uthmani · الإسبانية: ترجمة عيسى غارسيا · الإنجليزية: Saheeh International
const DAILY_VERSES = [{"surahNumber":26,"ayahNumber":85,"surahName":"Ash-Shu'araa","arabic":"وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ","translation_ar":"وٱجعلنى من ورثة جنة ٱلنعيم","translation_es":"Hazme estar entre los que heredarán el Jardín de las Delicias.","translation_en":"And place me among the inheritors of the Garden of Pleasure.","theme":"paradise"},{"surahNumber":36,"ayahNumber":1,"surahName":"Yaseen","arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يسٓ","translation_ar":"بسم ٱلله ٱلرحمن ٱلرحيم يسٓ","translation_es":"Iá’. Sín.","translation_en":"Ya, Seen.","theme":"mercy"},{"surahNumber":36,"ayahNumber":44,"surahName":"Yaseen","arabic":"إِلَّا رَحْمَةًۭ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍۢ","translation_ar":"إلا رحمة منا ومتعا إلى حين","translation_es":"pero por misericordia no lo hice, para que disfrutaran por un tiempo.","translation_en":"Except as a mercy from Us and provision for a time.","theme":"mercy"},{"surahNumber":43,"ayahNumber":27,"surahName":"Az-Zukhruf","arabic":"إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ","translation_ar":"إلا ٱلذى فطرنى فإنه سيهدين","translation_es":"Yo solo adoro a Quien me creó. Él me guiará”.","translation_en":"Except for He who created me; and indeed, He will guide me.\"","theme":"light"},{"surahNumber":55,"ayahNumber":14,"surahName":"Ar-Rahmaan","arabic":"خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ كَٱلْفَخَّارِ","translation_ar":"خلق ٱلإنسن من صلصل كٱلفخار","translation_es":"Creó al ser humano de arcilla como la cerámica,","translation_en":"He created man from clay like [that of] pottery.","theme":"creation"},{"surahNumber":55,"ayahNumber":15,"surahName":"Ar-Rahmaan","arabic":"وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍۢ مِّن نَّارٍۢ","translation_ar":"وخلق ٱلجآن من مارج من نار","translation_es":"y creó a los yinnes de fuego puro.","translation_en":"And He created the jinn from a smokeless flame of fire.","theme":"creation"},{"surahNumber":83,"ayahNumber":24,"surahName":"Al-Mutaffifin","arabic":"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ","translation_ar":"تعرف فى وجوههم نضرة ٱلنعيم","translation_es":"Reconocerás en sus rostros el resplandor de la dicha.","translation_en":"You will recognize in their faces the radiance of pleasure.","theme":"paradise"},{"surahNumber":14,"ayahNumber":15,"surahName":"Ibrahim","arabic":"وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍۢ","translation_ar":"وٱستفتحوا وخاب كل جبار عنيد","translation_es":"Entonces [los Mensajeros] pidieron el socorro de Dios, y todo prepotente y obstinado fue destruido,","translation_en":"And they requested victory from Allah, and disappointed, [therefore], was every obstinate tyrant.","theme":"victory"},{"surahNumber":20,"ayahNumber":122,"surahName":"Taa-Haa","arabic":"ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ","translation_ar":"ثم ٱجتبه ربه فتاب عليه وهدى","translation_es":"Más tarde, su Señor lo eligió [como Profeta], lo perdonó y lo guió.","translation_en":"Then his Lord chose him and turned to him in forgiveness and guided [him].","theme":"light"},{"surahNumber":23,"ayahNumber":73,"surahName":"Al-Muminoon","arabic":"وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"وإنك لتدعوهم إلى صرط مستقيم","translation_es":"Tú los invitas al camino recto.","translation_en":"And indeed, you invite them to a straight path.","theme":"light"},{"surahNumber":26,"ayahNumber":62,"surahName":"Ash-Shu'araa","arabic":"قَالَ كَلَّآ ۖ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ","translation_ar":"قال كلآ  إن معى ربى سيهدين","translation_es":"Dijo [Moisés]: “¡No, [no nos alcanzarán]! Pues mi Señor está conmigo, y Él me guiará [para saber cómo salvarnos]”.","translation_en":"[Moses] said, \"No! Indeed, with me is my Lord; He will guide me.\"","theme":"light"},{"surahNumber":36,"ayahNumber":61,"surahName":"Yaseen","arabic":"وَأَنِ ٱعْبُدُونِى ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","translation_ar":"وأن ٱعبدونى  هذا صرط مستقيم","translation_es":"y de que Me adorarían [solo a Mí]? Este es el sendero recto [que debían seguir].","translation_en":"And that you worship [only] Me? This is a straight path.","theme":"light"},{"surahNumber":38,"ayahNumber":54,"surahName":"Saad","arabic":"إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ","translation_ar":"إن هذا لرزقنا ما له من نفاد","translation_es":"Ese es Mi sustento, que jamás se agotará.","translation_en":"Indeed, this is Our provision; for it there is no depletion.","theme":"creation"},{"surahNumber":54,"ayahNumber":26,"surahName":"Al-Qamar","arabic":"سَيَعْلَمُونَ غَدًۭا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ","translation_ar":"سيعلمون غدا من ٱلكذاب ٱلأشر","translation_es":"¡Pero ya sabrán mañana quién es el verdadero mentiroso arrogante!","translation_en":"They will know tomorrow who is the insolent liar.","theme":"knowledge"},{"surahNumber":70,"ayahNumber":39,"surahName":"Al-Ma'aarij","arabic":"كَلَّآ ۖ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ","translation_ar":"كلآ  إنا خلقنهم مما يعلمون","translation_es":"No lo conseguirán. Los he creado de lo que saben. 1 Alusión al zakat o contribución social obligatoria. 2 De cometer aquello que es ilícito, como la fornicación o el adulterio.","translation_en":"No! Indeed, We have created them from that which they know.","theme":"knowledge"},{"surahNumber":76,"ayahNumber":12,"surahName":"Al-Insaan","arabic":"وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةًۭ وَحَرِيرًۭا","translation_ar":"وجزىهم بما صبروا جنة وحريرا","translation_es":"Los retribuirá por su paciencia con el Paraíso y vestimentas de seda.","translation_en":"And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].","theme":"paradise"},{"surahNumber":89,"ayahNumber":8,"surahName":"Al-Fajr","arabic":"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ","translation_ar":"ٱلتى لم يخلق مثلها فى ٱلبلد","translation_es":"que no tenía similar entre los otros pueblos [en su opulencia].","translation_en":"The likes of whom had never been created in the land?","theme":"creation"},{"surahNumber":92,"ayahNumber":19,"surahName":"Al-Lail","arabic":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ","translation_ar":"وما لأحد عنده من نعمة تجزىٓ","translation_es":"no anhelando una retribución ni favor [de otra persona],","translation_en":"And not [giving] for anyone who has [done him] a favor to be rewarded","theme":"creation"},{"surahNumber":21,"ayahNumber":107,"surahName":"Al-Anbiyaa","arabic":"وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةًۭ لِّلْعَٰلَمِينَ","translation_ar":"ومآ أرسلنك إلا رحمة للعلمين","translation_es":"No te he enviado [¡oh, Mujámmad!] sino como misericordia para todos los seres.","translation_en":"And We have not sent you, [O Muhammad], except as a mercy to the worlds.","theme":"mercy"},{"surahNumber":35,"ayahNumber":16,"surahName":"Faatir","arabic":"إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍۢ جَدِيدٍۢ","translation_ar":"إن يشأ يذهبكم ويأت بخلق جديد","translation_es":"Si Él quisiera, los haría desaparecer y crearía a otros seres [creyentes].","translation_en":"If He wills, He can do away with you and bring forth a new creation.","theme":"creation"},{"surahNumber":36,"ayahNumber":42,"surahName":"Yaseen","arabic":"وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ","translation_ar":"وخلقنا لهم من مثله ما يركبون","translation_es":"Y creé para ellos otras [barcas] en las que se embarcan.","translation_en":"And We created for them from the likes of it that which they ride.","theme":"creation"},{"surahNumber":37,"ayahNumber":99,"surahName":"As-Saaffaat","arabic":"وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ","translation_ar":"وقال إنى ذاهب إلى ربى سيهدين","translation_es":"Dijo [Abraham]: “Emigraré a donde mi Señor me ordene. ¡Él me guiará!","translation_en":"And [then] he said, \"Indeed, I will go to [where I am ordered by] my Lord; He will guide me.","theme":"light"},{"surahNumber":51,"ayahNumber":22,"surahName":"Adh-Dhaariyat","arabic":"وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ","translation_ar":"وفى ٱلسمآء رزقكم وما توعدون","translation_es":"En el cielo se encuentra [la fuente de] su sustento y lo que les fue prometido.","translation_en":"And in the heaven is your provision and whatever you are promised.","theme":"creation"},{"surahNumber":2,"ayahNumber":192,"surahName":"Al-Baqara","arabic":"فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"فإن ٱنتهوا فإن ٱلله غفور رحيم","translation_es":"Pero si ellos cesan de combatirlos, sepan que Dios es Absolvedor, Misericordioso.","translation_en":"And if they cease, then indeed, Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":16,"ayahNumber":42,"surahName":"An-Nahl","arabic":"ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ","translation_ar":"ٱلذين صبروا وعلى ربهم يتوكلون","translation_es":"Ellos fueron pacientes y se encomendaron plenamente a su Señor.","translation_en":"[They are] those who endured patiently and upon their Lord relied.","theme":"victory"},{"surahNumber":50,"ayahNumber":31,"surahName":"Qaaf","arabic":"وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ","translation_ar":"وأزلفت ٱلجنة للمتقين غير بعيد","translation_es":"Y el Paraíso será presentado a los piadosos, y no estará distante.","translation_en":"And Paradise will be brought near to the righteous, not far,","theme":"paradise"},{"surahNumber":56,"ayahNumber":59,"surahName":"Al-Waaqia","arabic":"ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ","translation_ar":"ءأنتم تخلقونهٓ أم نحن ٱلخلقون","translation_es":"¿Lo han creado ustedes o soy Yo el creador?","translation_en":"Is it you who creates it, or are We the Creator?","theme":"creation"},{"surahNumber":78,"ayahNumber":14,"surahName":"An-Naba","arabic":"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا","translation_ar":"وأنزلنا من ٱلمعصرت مآء ثجاجا","translation_es":"e hice descender de las nubes agua abundante","translation_en":"And sent down, from the rain clouds, pouring water","theme":"creation"},{"surahNumber":16,"ayahNumber":19,"surahName":"An-Nahl","arabic":"وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ","translation_ar":"وٱلله يعلم ما تسرون وما تعلنون","translation_es":"Dios sabe lo que ocultan y lo que manifiestan.","translation_en":"And Allah knows what you conceal and what you declare.","theme":"knowledge"},{"surahNumber":20,"ayahNumber":2,"surahName":"Taa-Haa","arabic":"مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ","translation_ar":"مآ أنزلنا عليك ٱلقرءان لتشقىٓ","translation_es":"No te he revelado el Corán para que te agobie,","translation_en":"We have not sent down to you the Qur'an that you be distressed","theme":"creation"},{"surahNumber":37,"ayahNumber":75,"surahName":"As-Saaffaat","arabic":"وَلَقَدْ نَادَىٰنَا نُوحٌۭ فَلَنِعْمَ ٱلْمُجِيبُونَ","translation_ar":"ولقد نادىنا نوح فلنعم ٱلمجيبون","translation_es":"Cuando Noé Me invocó, ¡y qué mejor que invocar a Quien responde todas las súplicas!,","translation_en":"And Noah had certainly called Us, and [We are] the best of responders.","theme":"hope"},{"surahNumber":38,"ayahNumber":49,"surahName":"Saad","arabic":"هَٰذَا ذِكْرٌۭ ۚ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍۢ","translation_ar":"هذا ذكر  وإن للمتقين لحسن مٔاب","translation_es":"Este es un Mensaje [para toda la humanidad]. Los piadosos tendrán una bella morada","translation_en":"This is a reminder. And indeed, for the righteous is a good place of return","theme":"light"},{"surahNumber":53,"ayahNumber":45,"surahName":"An-Najm","arabic":"وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ","translation_ar":"وأنه خلق ٱلزوجين ٱلذكر وٱلأنثى","translation_es":"Él ha creado la pareja: el macho y la hembra,","translation_en":"And that He creates the two mates - the male and female -","theme":"creation"},{"surahNumber":68,"ayahNumber":34,"surahName":"Al-Qalam","arabic":"إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ","translation_ar":"إن للمتقين عند ربهم جنت ٱلنعيم","translation_es":"El Señor agraciará a los piadosos con los Jardines de las Delicias.","translation_en":"Indeed, for the righteous with their Lord are the Gardens of Pleasure.","theme":"paradise"},{"surahNumber":88,"ayahNumber":17,"surahName":"Al-Ghaashiya","arabic":"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","translation_ar":"أفلا ينظرون إلى ٱلإبل كيف خلقت","translation_es":"¿Acaso no reflexionan [los que niegan la verdad] en la maravillosa creación del camello?","translation_en":"Then do they not look at the camels - how they are created?","theme":"creation"},{"surahNumber":37,"ayahNumber":57,"surahName":"As-Saaffaat","arabic":"وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ","translation_ar":"ولولا نعمة ربى لكنت من ٱلمحضرين","translation_es":"y de no ser por la gracia de mi Señor, habría sido uno de los condenados.","translation_en":"If not for the favor of my Lord, I would have been of those brought in [to Hell].","theme":"creation"},{"surahNumber":37,"ayahNumber":125,"surahName":"As-Saaffaat","arabic":"أَتَدْعُونَ بَعْلًۭا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ","translation_ar":"أتدعون بعلا وتذرون أحسن ٱلخلقين","translation_es":"Invocan a Ba‘l, y dejan de lado al mejor de los creadores:","translation_en":"Do you call upon Ba'l and leave the best of creators -","theme":"creation"},{"surahNumber":43,"ayahNumber":89,"surahName":"Az-Zukhruf","arabic":"فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌۭ ۚ فَسَوْفَ يَعْلَمُونَ","translation_ar":"فٱصفح عنهم وقل سلم  فسوف يعلمون","translation_es":"Apártate de ellos y [no respondas a sus ofensas, sino que] di: “¡Paz!”, ya habrán de saber [cuál será su destino].","translation_en":"So turn aside from them and say, \"Peace.\" But they are going to know.","theme":"knowledge"},{"surahNumber":54,"ayahNumber":35,"surahName":"Al-Qamar","arabic":"نِّعْمَةًۭ مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ","translation_ar":"نعمة من عندنا  كذلك نجزى من شكر","translation_es":"como una gracia de Mi parte, porque así retribuyo a quienes son agradecidos.","translation_en":"As favor from us. Thus do We reward he who is grateful.","theme":"creation"},{"surahNumber":95,"ayahNumber":4,"surahName":"At-Tin","arabic":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ","translation_ar":"لقد خلقنا ٱلإنسن فىٓ أحسن تقويم","translation_es":"Que he creado al ser humano con la mejor conformación.","translation_en":"We have certainly created man in the best of stature;","theme":"creation"},{"surahNumber":19,"ayahNumber":85,"surahName":"Maryam","arabic":"يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًۭا","translation_ar":"يوم نحشر ٱلمتقين إلى ٱلرحمن وفدا","translation_es":"El día que congregue a las delegaciones de piadosos ante el Compasivo,","translation_en":"On the Day We will gather the righteous to the Most Merciful as a delegation","theme":"light"},{"surahNumber":23,"ayahNumber":12,"surahName":"Al-Muminoon","arabic":"وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن سُلَٰلَةٍۢ مِّن طِينٍۢ","translation_ar":"ولقد خلقنا ٱلإنسن من سللة من طين","translation_es":"Creé al [primer] ser humano de barro.","translation_en":"And certainly did We create man from an extract of clay.","theme":"creation"},{"surahNumber":33,"ayahNumber":3,"surahName":"Al-Ahzaab","arabic":"وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا","translation_ar":"وتوكل على ٱلله  وكفى بٱلله وكيلا","translation_es":"Encomiéndate a Dios, porque Dios es suficiente como protector.","translation_en":"And rely upon Allah; and sufficient is Allah as Disposer of affairs.","theme":"ease"},{"surahNumber":36,"ayahNumber":55,"surahName":"Yaseen","arabic":"إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍۢ فَٰكِهُونَ","translation_ar":"إن أصحب ٱلجنة ٱليوم فى شغل فكهون","translation_es":"La gente del Paraíso, ese día, estarán felices disfrutando.","translation_en":"Indeed the companions of Paradise, that Day, will be amused in [joyful] occupation -","theme":"paradise"},{"surahNumber":37,"ayahNumber":150,"surahName":"As-Saaffaat","arabic":"أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًۭا وَهُمْ شَٰهِدُونَ","translation_ar":"أم خلقنا ٱلملٓئكة إنثا وهم شهدون","translation_es":"¿Acaso fueron testigos cuando creé a los ángeles, para afirmar que son de sexo femenino?","translation_en":"Or did We create the angels as females while they were witnesses?\"","theme":"creation"},{"surahNumber":43,"ayahNumber":70,"surahName":"Az-Zukhruf","arabic":"ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ","translation_ar":"ٱدخلوا ٱلجنة أنتم وأزوجكم تحبرون","translation_es":"Entren al Paraíso, ustedes y sus cónyuges, donde disfrutarán de las delicias.","translation_en":"Enter Paradise, you and your kinds, delighted.\"","theme":"paradise"},{"surahNumber":44,"ayahNumber":57,"surahName":"Ad-Dukhaan","arabic":"فَضْلًۭا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ","translation_ar":"فضلا من ربك  ذلك هو ٱلفوز ٱلعظيم","translation_es":"Ese es el favor de tu Señor. ¡Ese es el gran éxito!","translation_en":"As bounty from your Lord. That is what is the great attainment.","theme":"paradise"},{"surahNumber":44,"ayahNumber":58,"surahName":"Ad-Dukhaan","arabic":"فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ","translation_ar":"فإنما يسرنه بلسانك لعلهم يتذكرون","translation_es":"Para facilitar su comprensión lo he revelado [al Corán] en tu lengua, para que reflexionen.","translation_en":"And indeed, We have eased the Qur'an in your tongue that they might be reminded.","theme":"knowledge"},{"surahNumber":51,"ayahNumber":56,"surahName":"Adh-Dhaariyat","arabic":"وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ","translation_ar":"وما خلقت ٱلجن وٱلإنس إلا ليعبدون","translation_es":"No he creado a los yinnes y a los seres humanos sino para que Me adoren.","translation_en":"And I did not create the jinn and mankind except to worship Me.","theme":"creation"},{"surahNumber":54,"ayahNumber":11,"surahName":"Al-Qamar","arabic":"فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍۢ مُّنْهَمِرٍۢ","translation_ar":"ففتحنآ أبوب ٱلسمآء بمآء منهمر","translation_es":"Entonces abrí las puertas del cielo con un agua torrencial,","translation_en":"Then We opened the gates of the heaven with rain pouring down","theme":"victory"},{"surahNumber":79,"ayahNumber":27,"surahName":"An-Naazi'aat","arabic":"ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا","translation_ar":"ءأنتم أشد خلقا أم ٱلسمآء  بنىها","translation_es":"¿Acaso piensan que ustedes fueron más difíciles de crear que el cielo que Él edificó?","translation_en":"Are you a more difficult creation or is the heaven? Allah constructed it.","theme":"creation"},{"surahNumber":82,"ayahNumber":6,"surahName":"Al-Infitaar","arabic":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ","translation_ar":"يٓأيها ٱلإنسن ما غرك بربك ٱلكريم","translation_es":"¡Oh, seres humanos! ¿Qué fue lo que los engañó para que se apartaran de su Señor Generoso?","translation_en":"O mankind, what has deceived you concerning your Lord, the Generous,","theme":"mercy"},{"surahNumber":100,"ayahNumber":9,"surahName":"Al-Aadiyaat","arabic":"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","translation_ar":" أفلا يعلم إذا بعثر ما فى ٱلقبور","translation_es":"¿Acaso no sabe que cuando se haga surgir a quienes están en las sepulturas","translation_en":"But does he not know that when the contents of the graves are scattered","theme":"knowledge"},{"surahNumber":4,"ayahNumber":67,"surahName":"An-Nisaa","arabic":"وَإِذًۭا لَّءَاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًۭا","translation_ar":"وإذا لءاتينهم من لدنآ أجرا عظيما","translation_es":"les habría concedido una magnífica recompensa,","translation_en":"And then We would have given them from Us a great reward.","theme":"deeds"},{"surahNumber":26,"ayahNumber":184,"surahName":"Ash-Shu'araa","arabic":"وَٱتَّقُوا۟ ٱلَّذِى خَلَقَكُمْ وَٱلْجِبِلَّةَ ٱلْأَوَّلِينَ","translation_ar":"وٱتقوا ٱلذى خلقكم وٱلجبلة ٱلأولين","translation_es":"y tengan temor de Quien los creó, a ustedes y a las primeras generaciones”.","translation_en":"And fear He who created you and the former creation.\"","theme":"creation"},{"surahNumber":44,"ayahNumber":6,"surahName":"Ad-Dukhaan","arabic":"رَحْمَةًۭ مِّن رَّبِّكَ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","translation_ar":"رحمة من ربك  إنه هو ٱلسميع ٱلعليم","translation_es":"como una misericordia de tu Señor. Él todo lo oye, todo lo sabe.","translation_en":"As mercy from your Lord. Indeed, He is the Hearing, the Knowing.","theme":"mercy"},{"surahNumber":52,"ayahNumber":35,"surahName":"At-Tur","arabic":"أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ","translation_ar":"أم خلقوا من غير شىء أم هم ٱلخلقون","translation_es":"¿Acaso surgieron de la nada o son ellos sus propios creadores?","translation_en":"Or were they created by nothing, or were they the creators [of themselves]?","theme":"creation"},{"surahNumber":52,"ayahNumber":40,"surahName":"At-Tur","arabic":"أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ","translation_ar":"أم تسٔلهم أجرا فهم من مغرم مثقلون","translation_es":"¿O acaso tú [¡oh, Mujámmad!] les pides una retribución que hace que se vean abrumados por las deudas12?","translation_en":"Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down?","theme":"deeds"},{"surahNumber":67,"ayahNumber":14,"surahName":"Al-Mulk","arabic":"أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ","translation_ar":"ألا يعلم من خلق وهو ٱللطيف ٱلخبير","translation_es":"¿Acaso no lo va a saber Quien todo lo creó? Él es el Sutil, el que está bien informado.","translation_en":"Does He who created not know, while He is the Subtle, the Acquainted?","theme":"mercy"},{"surahNumber":2,"ayahNumber":2,"surahName":"Al-Baqara","arabic":"ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ","translation_ar":"ذلك ٱلكتب لا ريب  فيه  هدى للمتقين","translation_es":"Este es el Libro del cual no hay duda, es guía para los que son conscientes de Dios y le temen devocionalmente,","translation_en":"This is the Book about which there is no doubt, a guidance for those conscious of Allah -","theme":"light"},{"surahNumber":3,"ayahNumber":138,"surahName":"Aal-i-Imraan","arabic":"هَٰذَا بَيَانٌۭ لِّلنَّاسِ وَهُدًۭى وَمَوْعِظَةٌۭ لِّلْمُتَّقِينَ","translation_ar":"هذا بيان للناس وهدى وموعظة للمتقين","translation_es":"Esto debería ser una lección clara para la humanidad, y es guía y motivo de reflexión para los que tienen temor de Dios.","translation_en":"This [Qur'an] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allah.","theme":"light"},{"surahNumber":7,"ayahNumber":191,"surahName":"Al-A'raaf","arabic":"أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ","translation_ar":"أيشركون ما لا يخلق شئا وهم يخلقون","translation_es":"¿Acaso adoran a quienes no pueden crear nada, sino por el contrario, ellos mismos fueron creados?","translation_en":"Do they associate with Him those who create nothing and they are [themselves] created?","theme":"creation"},{"surahNumber":15,"ayahNumber":27,"surahName":"Al-Hijr","arabic":"وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ","translation_ar":"وٱلجآن خلقنه من قبل من نار ٱلسموم","translation_es":"Y al yinn lo había creado ya antes de fuego.","translation_en":"And the jinn We created before from scorching fire.","theme":"creation"},{"surahNumber":15,"ayahNumber":49,"surahName":"Al-Hijr","arabic":"۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ","translation_ar":" نبئ عبادىٓ أنىٓ أنا ٱلغفور ٱلرحيم","translation_es":"Anúnciales a Mis siervos [oh, Mujámmad] que soy el Absolvedor, el Misericordioso,","translation_en":"[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.","theme":"hope"},{"surahNumber":16,"ayahNumber":17,"surahName":"An-Nahl","arabic":"أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ","translation_ar":"أفمن يخلق كمن لا يخلق  أفلا تذكرون","translation_es":"¿Es procedente comparar a Quien es capaz de crear con quien no puede crear nada? ¿Acaso no recapacitan?","translation_en":"Then is He who creates like one who does not create? So will you not be reminded?","theme":"creation"},{"surahNumber":20,"ayahNumber":4,"surahName":"Taa-Haa","arabic":"تَنزِيلًۭا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَٰوَٰتِ ٱلْعُلَى","translation_ar":"تنزيلا ممن خلق ٱلأرض وٱلسموت ٱلعلى","translation_es":"[El Corán] fue revelado por Quien creó la Tierra y los altos cielos;","translation_en":"A revelation from He who created the earth and highest heavens,","theme":"creation"},{"surahNumber":26,"ayahNumber":93,"surahName":"Ash-Shu'araa","arabic":"مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ","translation_ar":"من دون ٱلله هل ينصرونكم أو ينتصرون","translation_es":"en lugar de Dios? ¿Acaso pueden ellos socorrerlos o siquiera defenderse a sí mismos?”","translation_en":"Other than Allah? Can they help you or help themselves?\"","theme":"victory"},{"surahNumber":28,"ayahNumber":69,"surahName":"Al-Qasas","arabic":"وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ","translation_ar":"وربك يعلم ما تكن صدورهم وما يعلنون","translation_es":"Tu Señor conoce lo que ocultan y lo que manifiestan sus corazones.","translation_en":"And your Lord knows what their breasts conceal and what they declare.","theme":"knowledge"},{"surahNumber":36,"ayahNumber":16,"surahName":"Yaseen","arabic":"قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ","translation_ar":"قالوا ربنا يعلم إنآ إليكم لمرسلون","translation_es":"Dijeron [los Mensajeros]: “Nuestro Señor sabe que realmente somos Mensajeros.","translation_en":"They said, \"Our Lord knows that we are messengers to you,","theme":"knowledge"},{"surahNumber":40,"ayahNumber":19,"surahName":"Ghafir","arabic":"يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ","translation_ar":"يعلم خآئنة ٱلأعين وما تخفى ٱلصدور","translation_es":"[Dios] conoce las miradas pérfidas y lo que esconden los corazones.","translation_en":"He knows that which deceives the eyes and what the breasts conceal.","theme":"knowledge"},{"surahNumber":4,"ayahNumber":70,"surahName":"An-Nisaa","arabic":"ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًۭا","translation_ar":"ذلك ٱلفضل من ٱلله  وكفى بٱلله عليما","translation_es":"Esa es la generosidad de Dios. Y Dios es el único que todo lo sabe.","translation_en":"That is the bounty from Allah, and sufficient is Allah as Knower.","theme":"ease"},{"surahNumber":11,"ayahNumber":115,"surahName":"Hud","arabic":"وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ","translation_ar":"وٱصبر فإن ٱلله لا يضيع أجر ٱلمحسنين","translation_es":"Sé paciente [ante las dificultades], porque Dios no dejará que se pierda la recompensa de los que hacen el bien.","translation_en":"And be patient, for indeed, Allah does not allow to be lost the reward of those who do good.","theme":"mercy"},{"surahNumber":27,"ayahNumber":79,"surahName":"An-Naml","arabic":"فَتَوَكَّلْ عَلَى ٱللَّهِ ۖ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ","translation_ar":"فتوكل على ٱلله  إنك على ٱلحق ٱلمبين","translation_es":"Encomiéndate a Dios, que tú estás en la verdad evidente.","translation_en":"So rely upon Allah; indeed, you are upon the clear truth.","theme":"victory"},{"surahNumber":28,"ayahNumber":51,"surahName":"Al-Qasas","arabic":"۞ وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ","translation_ar":" ولقد وصلنا لهم ٱلقول لعلهم يتذكرون","translation_es":"Les he revelado la palabra para que reflexionen.","translation_en":"And We have [repeatedly] conveyed to them the Qur'an that they might be reminded.","theme":"knowledge"},{"surahNumber":32,"ayahNumber":6,"surahName":"As-Sajda","arabic":"ذَٰلِكَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ","translation_ar":"ذلك علم ٱلغيب وٱلشهدة ٱلعزيز ٱلرحيم","translation_es":"Él es Quien conoce lo oculto y lo manifiesto. Él es el Poderoso, el Misericordioso,","translation_en":"That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,","theme":"mercy"},{"surahNumber":32,"ayahNumber":28,"surahName":"As-Sajda","arabic":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ","translation_ar":"ويقولون متى هذا ٱلفتح إن كنتم صدقين","translation_es":"Y preguntan [a los creyentes]: “¿Cuándo llegará el Día del Juicio, si es que dicen la verdad?”","translation_en":"And they say, \"When will be this conquest, if you should be truthful?\"","theme":"victory"},{"surahNumber":36,"ayahNumber":21,"surahName":"Yaseen","arabic":"ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًۭا وَهُم مُّهْتَدُونَ","translation_ar":"ٱتبعوا من لا يسٔلكم أجرا وهم مهتدون","translation_es":"Sigan a quienes no les piden retribución alguna [por transmitirles el conocimiento], y están bien guiados.","translation_en":"Follow those who do not ask of you [any] payment, and they are [rightly] guided.","theme":"deeds"},{"surahNumber":50,"ayahNumber":41,"surahName":"Qaaf","arabic":"وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍۢ قَرِيبٍۢ","translation_ar":"وٱستمع يوم يناد ٱلمناد من مكان قريب","translation_es":"Mantente siempre alerta del día que convoque el pregonero desde un lugar cercano;","translation_en":"And listen on the Day when the Caller will call out from a place that is near -","theme":"hope"},{"surahNumber":51,"ayahNumber":49,"surahName":"Adh-Dhaariyat","arabic":"وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ","translation_ar":"ومن كل شىء خلقنا زوجين لعلكم تذكرون","translation_es":"Y todo lo he creado en parejas, para que reflexionen.","translation_en":"And of all things We created two mates; perhaps you will remember.","theme":"creation"},{"surahNumber":70,"ayahNumber":38,"surahName":"Al-Ma'aarij","arabic":"أَيَطْمَعُ كُلُّ ٱمْرِئٍۢ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍۢ","translation_ar":"أيطمع كل ٱمرئ منهم أن يدخل جنة نعيم","translation_es":"¿Acaso anhelan ser introducidos en los Jardines de las Delicias?","translation_en":"Does every person among them aspire to enter a garden of pleasure?","theme":"paradise"},{"surahNumber":76,"ayahNumber":20,"surahName":"Al-Insaan","arabic":"وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًۭا وَمُلْكًۭا كَبِيرًا","translation_ar":"وإذا رأيت ثم رأيت نعيما وملكا كبيرا","translation_es":"Y al mirar solo encontrarás felicidad y un reino vasto.","translation_en":"And when you look there [in Paradise], you will see pleasure and great dominion.","theme":"paradise"},{"surahNumber":12,"ayahNumber":2,"surahName":"Yusuf","arabic":"إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ","translation_ar":"إنآ أنزلنه قرءنا عربيا لعلكم تعقلون","translation_es":"He descendido el Corán en idioma árabe para que puedan comprender sus significados en su contexto.","translation_en":"Indeed, We have sent it down as an Arabic Qur'an that you might understand.","theme":"creation"},{"surahNumber":17,"ayahNumber":14,"surahName":"Al-Israa","arabic":"ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًۭا","translation_ar":"ٱقرأ كتبك كفى بنفسك ٱليوم عليك حسيبا","translation_es":"[Se le dirá:] “Lee tu libro, pues hoy será suficiente con que tú mismo leas el registro de tus obras [para saber cuál será tu destino]”.","translation_en":"[It will be said], \"Read your record. Sufficient is yourself against you this Day as accountant.\"","theme":"ease"},{"surahNumber":20,"ayahNumber":7,"surahName":"Taa-Haa","arabic":"وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى","translation_ar":"وإن تجهر بٱلقول فإنه يعلم ٱلسر وأخفى","translation_es":"Dios conoce lo que pronuncias en voz alta, las confidencias que dices en voz baja y lo que está aún más oculto [los pensamientos].","translation_en":"And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden.","theme":"knowledge"},{"surahNumber":36,"ayahNumber":26,"surahName":"Yaseen","arabic":"قِيلَ ٱدْخُلِ ٱلْجَنَّةَ ۖ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ","translation_ar":"قيل ٱدخل ٱلجنة  قال يليت قومى يعلمون","translation_es":"Entonces le fue dicho: “Ingresa al Paraíso”. Dijo: “¡Ojalá mi pueblo supiera","translation_en":"It was said, \"Enter Paradise.\" He said, \"I wish my people could know","theme":"paradise"},{"surahNumber":39,"ayahNumber":62,"surahName":"Az-Zumar","arabic":"ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ","translation_ar":"ٱلله خلق كل شىء  وهو على كل شىء وكيل","translation_es":"Dios es el Creador de todas las cosas, y Él es su Custodio.","translation_en":"Allah is the Creator of all things, and He is, over all things, Disposer of affairs.","theme":"victory"},{"surahNumber":2,"ayahNumber":52,"surahName":"Al-Baqara","arabic":"ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ","translation_ar":"ثم عفونا عنكم من بعد ذلك لعلكم تشكرون","translation_es":"Luego, a pesar de eso, los perdoné para que fueran agradecidos.","translation_en":"Then We forgave you after that so perhaps you would be grateful.","theme":"mercy"},{"surahNumber":4,"ayahNumber":106,"surahName":"An-Nisaa","arabic":"وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا","translation_ar":"وٱستغفر ٱلله  إن ٱلله كان غفورا رحيما","translation_es":"Pide perdón a Dios, porque Dios es Perdonador, Misericordioso.","translation_en":"And seek forgiveness of Allah. Indeed, Allah is ever Forgiving and Merciful.","theme":"hope"},{"surahNumber":7,"ayahNumber":199,"surahName":"Al-A'raaf","arabic":"خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ","translation_ar":"خذ ٱلعفو وأمر بٱلعرف وأعرض عن ٱلجهلين","translation_es":"[¡Oh, Mujámmad!] Ante todo, elige perdonar, ordena el bien y apártate de quienes se comportan contigo en forma ignorante.","translation_en":"Take what is given freely, enjoin what is good, and turn away from the ignorant.","theme":"mercy"},{"surahNumber":36,"ayahNumber":68,"surahName":"Yaseen","arabic":"وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ","translation_ar":"ومن نعمره ننكسه فى ٱلخلق  أفلا يعقلون","translation_es":"A quien le concedo una vida larga, hago que se vuelva débil [como cuando era pequeño]. ¿Acaso no van a reflexionar?","translation_en":"And he to whom We grant long life We reverse in creation; so will they not understand?","theme":"knowledge"},{"surahNumber":43,"ayahNumber":16,"surahName":"Az-Zukhruf","arabic":"أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍۢ وَأَصْفَىٰكُم بِٱلْبَنِينَ","translation_ar":"أم ٱتخذ مما يخلق بنات وأصفىكم بٱلبنين","translation_es":"¿Acaso Dios tomaría para Sí hijas de entre Sus criaturas, y a ustedes les dejaría los hijos varones?","translation_en":"Or has He taken, out of what He has created, daughters and chosen you for [having] sons?","theme":"creation"},{"surahNumber":44,"ayahNumber":42,"surahName":"Ad-Dukhaan","arabic":"إِلَّا مَن رَّحِمَ ٱللَّهُ ۚ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","translation_ar":"إلا من رحم ٱلله  إنه هو ٱلعزيز ٱلرحيم","translation_es":"excepto aquel de quien Dios tenga misericordia. Él es el Poderoso, el Misericordioso.","translation_en":"Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful.","theme":"mercy"},{"surahNumber":71,"ayahNumber":16,"surahName":"Nooh","arabic":"وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًۭا وَجَعَلَ ٱلشَّمْسَ سِرَاجًۭا","translation_ar":"وجعل ٱلقمر فيهن نورا وجعل ٱلشمس سراجا","translation_es":"Puso en ellos la Luna para que refleje la luz y el Sol [para que la irradie] como lámpara.","translation_en":"And made the moon therein a [reflected] light and made the sun a burning lamp?","theme":"light"},{"surahNumber":2,"ayahNumber":241,"surahName":"Al-Baqara","arabic":"وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ","translation_ar":"وللمطلقت متع بٱلمعروف  حقا على ٱلمتقين","translation_es":"Quienes divorcien a su esposa deben mantenerla de manera honorable. Esto es un deber para los piadosos.","translation_en":"And for divorced women is a provision according to what is acceptable - a duty upon the righteous.","theme":"light"},{"surahNumber":3,"ayahNumber":48,"surahName":"Aal-i-Imraan","arabic":"وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","translation_ar":"ويعلمه ٱلكتب وٱلحكمة وٱلتورىة وٱلإنجيل","translation_es":"Él le enseñará la escritura, le concederá la sabiduría, le enseñará la Tora y el Evangelio.","translation_en":"And He will teach him writing and wisdom and the Torah and the Gospel","theme":"knowledge"},{"surahNumber":7,"ayahNumber":181,"surahName":"Al-A'raaf","arabic":"وَمِمَّنْ خَلَقْنَآ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ","translation_ar":"وممن خلقنآ أمة يهدون بٱلحق وبه يعدلون","translation_es":"Algunos de Mi creación guían [a la gente] con la Verdad, y acorde a ella establecen justicia.","translation_en":"And among those We created is a community which guides by truth and thereby establishes justice.","theme":"creation"},{"surahNumber":8,"ayahNumber":3,"surahName":"Al-Anfaal","arabic":"ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ","translation_ar":"ٱلذين يقيمون ٱلصلوة ومما رزقنهم ينفقون","translation_es":"[Los creyentes] son quienes realizan la oración y dan en caridad parte de lo que les he proveído.","translation_en":"The ones who establish prayer, and from what We have provided them, they spend.","theme":"deeds"},{"surahNumber":15,"ayahNumber":56,"surahName":"Al-Hijr","arabic":"قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ","translation_ar":"قال ومن يقنط من رحمة ربهٓ إلا ٱلضآلون","translation_es":"Dijo: “Solo desesperan de la misericordia de su Señor los extraviados”.","translation_en":"He said, \"And who despairs of the mercy of his Lord except for those astray?\"","theme":"mercy"},{"surahNumber":16,"ayahNumber":47,"surahName":"An-Nahl","arabic":"أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍۢ فَإِنَّ رَبَّكُمْ لَرَءُوفٌۭ رَّحِيمٌ","translation_ar":"أو يأخذهم على تخوف فإن ربكم لرءوف رحيم","translation_es":"¿O de que los alcance una lenta decadencia? Su Señor es Compasivo, Misericordioso [y no les adelantará el castigo].","translation_en":"Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful.","theme":"mercy"},{"surahNumber":20,"ayahNumber":50,"surahName":"Taa-Haa","arabic":"قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ","translation_ar":"قال ربنا ٱلذىٓ أعطى كل شىء خلقه ثم هدى","translation_es":"Dijo [Moisés]: “Nuestro Señor es Quien creó todo con una naturaleza particular, y luego lo encamina [para que cumpla su destino]”.","translation_en":"He said, \"Our Lord is He who gave each thing its form and then guided [it].\"","theme":"light"},{"surahNumber":27,"ayahNumber":74,"surahName":"An-Naml","arabic":"وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ","translation_ar":"وإن ربك ليعلم ما تكن صدورهم وما يعلنون","translation_es":"Tu Señor conoce lo que esconden sus corazones y lo que manifiestan.","translation_en":"And indeed, your Lord knows what their breasts conceal and what they declare.","theme":"knowledge"},{"surahNumber":29,"ayahNumber":35,"surahName":"Al-Ankaboot","arabic":"وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةًۭ لِّقَوْمٍۢ يَعْقِلُونَ","translation_ar":"ولقد تركنا منهآ ءاية بينة لقوم يعقلون","translation_es":"Dejé [vestigios] de ella como un signo claro, para que reflexionaran.","translation_en":"And We have certainly left of it a sign as clear evidence for a people who use reason.","theme":"knowledge"},{"surahNumber":36,"ayahNumber":74,"surahName":"Yaseen","arabic":"وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لَّعَلَّهُمْ يُنصَرُونَ","translation_ar":"وٱتخذوا من دون ٱلله ءالهة لعلهم ينصرون","translation_es":"Pero toman falsas divinidades, en lugar de Dios, para que los socorran.","translation_en":"But they have taken besides Allah [false] deities that perhaps they would be helped.","theme":"victory"},{"surahNumber":38,"ayahNumber":9,"surahName":"Saad","arabic":"أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ","translation_ar":"أم عندهم خزآئن رحمة ربك ٱلعزيز ٱلوهاب","translation_es":"¿Acaso ellos poseen las llaves de la misericordia de tu Señor, el Poderoso, el Dadivoso?","translation_en":"Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?","theme":"mercy"},{"surahNumber":38,"ayahNumber":20,"surahName":"Saad","arabic":"وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ","translation_ar":"وشددنا ملكه وءاتينه ٱلحكمة وفصل ٱلخطاب","translation_es":"Afiancé su reino, lo agracié con la sabiduría [la profecía] y un juicio certero.","translation_en":"And We strengthened his kingdom and gave him wisdom and discernment in speech.","theme":"knowledge"},{"surahNumber":45,"ayahNumber":20,"surahName":"Al-Jaathiya","arabic":"هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًۭى وَرَحْمَةٌۭ لِّقَوْمٍۢ يُوقِنُونَ","translation_ar":"هذا بصٓئر للناس وهدى ورحمة لقوم يوقنون","translation_es":"Ésta revelación es luz para la gente. Una guía y una misericordia para quienes tienen certeza.","translation_en":"This [Qur'an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].","theme":"mercy"},{"surahNumber":47,"ayahNumber":17,"surahName":"Muhammad","arabic":"وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًۭى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ","translation_ar":"وٱلذين ٱهتدوا زادهم هدى وءاتىهم تقوىهم","translation_es":"Pero a quienes siguen la guía, Él les incrementará su fe y su piedad.","translation_en":"And those who are guided - He increases them in guidance and gives them their righteousness.","theme":"light"},{"surahNumber":15,"ayahNumber":20,"surahName":"Al-Hijr","arabic":"وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ","translation_ar":"وجعلنا لكم فيها معيش ومن لستم له برزقين","translation_es":"Facilité los medios para que puedan vivir en ella ustedes y el resto de las criaturas.","translation_en":"And We have made for you therein means of living and [for] those for whom you are not providers.","theme":"creation"},{"surahNumber":20,"ayahNumber":8,"surahName":"Taa-Haa","arabic":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ","translation_ar":"ٱلله لآ إله إلا هو  له ٱلأسمآء ٱلحسنى","translation_es":"¡Dios! No hay más divinidad que Él. A Él pertenecen los nombres [y los atributos] más sublimes.","translation_en":"Allah - there is no deity except Him. To Him belong the best names.","theme":"paradise"},{"surahNumber":21,"ayahNumber":50,"surahName":"Al-Anbiyaa","arabic":"وَهَٰذَا ذِكْرٌۭ مُّبَارَكٌ أَنزَلْنَٰهُ ۚ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ","translation_ar":"وهذا ذكر مبارك أنزلنه  أفأنتم له منكرون","translation_es":"Este [Corán] es un Mensaje bendito que he revelado. ¿Acaso van a rechazarlo?","translation_en":"And this [Qur'an] is a blessed message which We have sent down. Then are you with it unacquainted?","theme":"creation"},{"surahNumber":21,"ayahNumber":110,"surahName":"Al-Anbiyaa","arabic":"إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ","translation_ar":"إنه يعلم ٱلجهر من ٱلقول ويعلم ما تكتمون","translation_es":"Él bien sabe tanto lo que dicen abiertamente como lo que dicen en secreto.","translation_en":"Indeed, He knows what is declared of speech, and He knows what you conceal.","theme":"knowledge"},{"surahNumber":23,"ayahNumber":25,"surahName":"Al-Muminoon","arabic":"إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌۭ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍۢ","translation_ar":"إن هو إلا رجل به جنة فتربصوا به حتى حين","translation_es":"[Noé] no es más que un demente, sopórtenlo por un tiempo [hasta que muera]”.","translation_en":"He is not but a man possessed with madness, so wait concerning him for a time.\"","theme":"paradise"},{"surahNumber":25,"ayahNumber":24,"surahName":"Al-Furqaan","arabic":"أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌۭ مُّسْتَقَرًّۭا وَأَحْسَنُ مَقِيلًۭا","translation_ar":"أصحب ٱلجنة يومئذ خير مستقرا وأحسن مقيلا","translation_es":"En cambio, los moradores del Paraíso tendrán la mejor morada y el mejor lugar de descanso.","translation_en":"The companions of Paradise, that Day, are [in] a better settlement and better resting place.","theme":"paradise"},{"surahNumber":30,"ayahNumber":59,"surahName":"Ar-Room","arabic":"كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ","translation_ar":"كذلك يطبع ٱلله على قلوب ٱلذين لا يعلمون","translation_es":"Así es como Dios sella los corazones de los que no quieren conocer [la verdad].","translation_en":"Thus does Allah seal the hearts of those who do not know.","theme":"knowledge"},{"surahNumber":37,"ayahNumber":105,"surahName":"As-Saaffaat","arabic":"قَدْ صَدَّقْتَ ٱلرُّءْيَآ ۚ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translation_ar":"قد صدقت ٱلرءيآ  إنا كذلك نجزى ٱلمحسنين","translation_es":"Has cumplido con lo que viste [en tus sueños]. Así recompenso a los que hacen el bien”.","translation_en":"You have fulfilled the vision.\" Indeed, We thus reward the doers of good.","theme":"mercy"},{"surahNumber":38,"ayahNumber":71,"surahName":"Saad","arabic":"إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن طِينٍۢ","translation_ar":"إذ قال ربك للملٓئكة إنى خلق بشرا من طين","translation_es":"Recuerda [¡oh, Mujámmad!] cuando tu Señor dijo a los ángeles: “Voy a crear un hombre de barro.","translation_en":"[So mention] when your Lord said to the angels, \"Indeed, I am going to create a human being from clay.","theme":"creation"},{"surahNumber":41,"ayahNumber":3,"surahName":"Fussilat","arabic":"كِتَٰبٌۭ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّۭا لِّقَوْمٍۢ يَعْلَمُونَ","translation_ar":"كتب فصلت ءايته قرءانا عربيا لقوم يعلمون","translation_es":"un Libro en que los signos son explicados detalladamente. Expresado en idioma árabe para gente que comprende.","translation_en":"A Book whose verses have been detailed, an Arabic Qur'an for a people who know,","theme":"knowledge"},{"surahNumber":56,"ayahNumber":69,"surahName":"Al-Waaqia","arabic":"ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ","translation_ar":"ءأنتم أنزلتموه من ٱلمزن أم نحن ٱلمنزلون","translation_es":"¿Ustedes la hacen descender de las nubes o soy Yo Quien la hago descender?","translation_en":"Is it you who brought it down from the clouds, or is it We who bring it down?","theme":"creation"},{"surahNumber":7,"ayahNumber":192,"surahName":"Al-A'raaf","arabic":"وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًۭا وَلَآ أَنفُسَهُمْ يَنصُرُونَ","translation_ar":"ولا يستطيعون لهم نصرا ولآ أنفسهم ينصرون","translation_es":"No pueden auxiliarlos, ni tampoco auxiliarse a sí mismos.","translation_en":"And the false deities are unable to [give] them help, nor can they help themselves.","theme":"victory"},{"surahNumber":9,"ayahNumber":22,"surahName":"At-Tawba","arabic":"خَٰلِدِينَ فِيهَآ أَبَدًا ۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ","translation_ar":"خلدين فيهآ أبدا  إن ٱلله عندهٓ أجر عظيم","translation_es":"Vivirán en ellos por toda la eternidad. Dios les tiene reservada una recompensa grandiosa.","translation_en":"[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.","theme":"deeds"},{"surahNumber":16,"ayahNumber":3,"surahName":"An-Nahl","arabic":"خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ","translation_ar":"خلق ٱلسموت وٱلأرض بٱلحق  تعلى عما يشركون","translation_es":"Dios creó los cielos y la Tierra con un fin justo y verdadero. Él está por encima de cuanto Le asocian.","translation_en":"He created the heavens and earth in truth. High is He above what they associate with Him.","theme":"creation"},{"surahNumber":26,"ayahNumber":22,"surahName":"Ash-Shu'araa","arabic":"وَتِلْكَ نِعْمَةٌۭ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ","translation_ar":"وتلك نعمة تمنها على أن عبدت بنىٓ إسرٓءيل","translation_es":"En cuanto al favor que me recuerdas, ¿acaso no se debió a que habías esclavizado a los Hijos de Israel?”","translation_en":"And is this a favor of which you remind me - that you have enslaved the Children of Israel?\"","theme":"creation"},{"surahNumber":26,"ayahNumber":82,"surahName":"Ash-Shu'araa","arabic":"وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ","translation_ar":"وٱلذىٓ أطمع أن يغفر لى خطيٓٔتى يوم ٱلدين","translation_es":"de Él anhelo que perdone mis pecados el Día del Juicio.","translation_en":"And who I aspire that He will forgive me my sin on the Day of Recompense.\"","theme":"hope"},{"surahNumber":27,"ayahNumber":30,"surahName":"An-Naml","arabic":"إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","translation_ar":"إنه من سليمن وإنه بسم ٱلله ٱلرحمن ٱلرحيم","translation_es":"Es de Salomón, y dice: ‘En el nombre de Dios, el Compasivo con toda la creación, el Misericordioso con los creyentes.","translation_en":"Indeed, it is from Solomon, and indeed, it reads: 'In the name of Allah, the Entirely Merciful, the Especially Merciful,","theme":"mercy"},{"surahNumber":27,"ayahNumber":70,"surahName":"An-Naml","arabic":"وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍۢ مِّمَّا يَمْكُرُونَ","translation_ar":"ولا تحزن عليهم ولا تكن فى ضيق مما يمكرون","translation_es":"No te entristezcas por ellos ni te angusties por lo que traman contra ti.","translation_en":"And grieve not over them or be in distress from what they conspire.","theme":"sadness"},{"surahNumber":30,"ayahNumber":11,"surahName":"Ar-Room","arabic":"ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ","translation_ar":"ٱلله يبدؤا ٱلخلق ثم يعيده ثم إليه ترجعون","translation_es":"Dios origina la creación y luego la reproduce, y ante Él regresarán.","translation_en":"Allah begins creation; then He will repeat it; then to Him you will be returned.","theme":"creation"},{"surahNumber":33,"ayahNumber":47,"surahName":"Al-Ahzaab","arabic":"وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًۭا كَبِيرًۭا","translation_ar":"وبشر ٱلمؤمنين بأن لهم من ٱلله فضلا كبيرا","translation_es":"Dales a los creyentes la albricia de que recibirán un inmenso favor de Dios.","translation_en":"And give good tidings to the believers that they will have from Allah great bounty.","theme":"creation"},{"surahNumber":39,"ayahNumber":57,"surahName":"Az-Zumar","arabic":"أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ","translation_ar":"أو تقول لو أن ٱلله هدىنى لكنت من ٱلمتقين","translation_es":"O digan: “¡Cómo desearía que Dios me hubiera guiado para contarme entre los piadosos!”","translation_en":"Or [lest] it say, \"If only Allah had guided me, I would have been among the righteous.\"","theme":"light"},{"surahNumber":44,"ayahNumber":38,"surahName":"Ad-Dukhaan","arabic":"وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ","translation_ar":"وما خلقنا ٱلسموت وٱلأرض وما بينهما لعبين","translation_es":"No he creado a los cielos, la Tierra y todo lo que hay entre ellos como un simple juego.","translation_en":"And We did not create the heavens and earth and that between them in play.","theme":"creation"},{"surahNumber":51,"ayahNumber":57,"surahName":"Adh-Dhaariyat","arabic":"مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ","translation_ar":"مآ أريد منهم من رزق ومآ أريد أن يطعمون","translation_es":"No pretendo de ellos ningún sustento ni quiero que Me alimenten,","translation_en":"I do not want from them any provision, nor do I want them to feed Me.","theme":"creation"},{"surahNumber":52,"ayahNumber":28,"surahName":"At-Tur","arabic":"إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ ۖ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ","translation_ar":"إنا كنا من قبل ندعوه  إنه هو ٱلبر ٱلرحيم","translation_es":"A Él le suplicábamos, pues Él es el Bondadoso, el Misericordioso”.","translation_en":"Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful.\"","theme":"mercy"},{"surahNumber":73,"ayahNumber":11,"surahName":"Al-Muzzammil","arabic":"وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا","translation_ar":"وذرنى وٱلمكذبين أولى ٱلنعمة ومهلهم قليلا","translation_es":"Deja que Yo me ocupe de los que niegan la verdad, los que ahora tienen opulencia. Tenles paciencia brevemente.","translation_en":"And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.","theme":"creation"},{"surahNumber":3,"ayahNumber":51,"surahName":"Aal-i-Imraan","arabic":"إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","translation_ar":"إن ٱلله ربى وربكم فٱعبدوه  هذا صرط مستقيم","translation_es":"Dios es mi Señor y el de ustedes. ¡Adórenlo! Ese es el sendero recto”.”","translation_en":"Indeed, Allah is my Lord and your Lord, so worship Him. That is the straight path.\"","theme":"light"},{"surahNumber":4,"ayahNumber":28,"surahName":"An-Nisaa","arabic":"يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًۭا","translation_ar":"يريد ٱلله أن يخفف عنكم  وخلق ٱلإنسن ضعيفا","translation_es":"Dios facilita las cosas, ya que el ser humano fue creado con una naturaleza débil.","translation_en":"And Allah wants to lighten for you [your difficulties]; and mankind was created weak.","theme":"creation"},{"surahNumber":6,"ayahNumber":66,"surahName":"Al-An'aam","arabic":"وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍۢ","translation_ar":"وكذب به قومك وهو ٱلحق  قل لست عليكم بوكيل","translation_es":"Pero tu pueblo lo ha negado, siendo que es la verdad. Diles: “Yo no soy responsable de lo que hacen”.","translation_en":"But your people have denied it while it is the truth. Say, \"I am not over you a manager.\"","theme":"victory"},{"surahNumber":16,"ayahNumber":121,"surahName":"An-Nahl","arabic":"شَاكِرًۭا لِّأَنْعُمِهِ ۚ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"شاكرا لأنعمه  ٱجتبىه وهدىه إلى صرط مستقيم","translation_es":"Era agradecido por los favores de Dios. Él lo eligió y lo guió por el sendero recto.","translation_en":"[He was] grateful for His favors. Allah chose him and guided him to a straight path.","theme":"light"},{"surahNumber":19,"ayahNumber":63,"surahName":"Maryam","arabic":"تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّۭا","translation_ar":"تلك ٱلجنة ٱلتى نورث من عبادنا من كان تقيا","translation_es":"Ése es el Paraíso que haremos heredar a quienes de Mis siervos hayan sido piadosos.","translation_en":"That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allah.","theme":"paradise"},{"surahNumber":27,"ayahNumber":29,"surahName":"An-Naml","arabic":"قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌۭ كَرِيمٌ","translation_ar":"قالت يٓأيها ٱلملؤا إنىٓ ألقى إلى كتب كريم","translation_es":"Ella [la reina de Saba] dijo: “¡Oh, nobles! Me han entregado una carta noble. toda la creación, el Misericordioso con los creyentes.","translation_en":"She said, \"O eminent ones, indeed, to me has been delivered a noble letter.","theme":"mercy"},{"surahNumber":43,"ayahNumber":67,"surahName":"Az-Zukhruf","arabic":"ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ","translation_ar":"ٱلأخلآء يومئذ بعضهم لبعض عدو إلا ٱلمتقين","translation_es":"Ese día los amigos serán enemigos unos de otros, excepto los que hayan tenido temor de Dios.","translation_en":"Close friends, that Day, will be enemies to each other, except for the righteous","theme":"light"},{"surahNumber":52,"ayahNumber":46,"surahName":"At-Tur","arabic":"يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ","translation_ar":"يوم لا يغنى عنهم كيدهم شئا ولا هم ينصرون","translation_es":"Ese día no los beneficiarán en nada sus argucias y nadie los auxiliará.","translation_en":"The Day their plan will not avail them at all, nor will they be helped.","theme":"victory"},{"surahNumber":87,"ayahNumber":7,"surahName":"Al-A'laa","arabic":"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","translation_ar":"إلا ما شآء ٱلله  إنه يعلم ٱلجهر وما يخفى","translation_es":"Salvo que Dios quiera, pues Él conoce lo manifiesto y lo oculto.","translation_en":"Except what Allah should will. Indeed, He knows what is declared and what is hidden.","theme":"knowledge"},{"surahNumber":7,"ayahNumber":16,"surahName":"Al-A'raaf","arabic":"قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ","translation_ar":"قال فبمآ أغويتنى لأقعدن لهم صرطك ٱلمستقيم","translation_es":"Dijo [el Demonio]: “Por haberme descarriado los acecharé para apartarlos de Tu sendero recto.","translation_en":"[Satan] said, \"Because You have put me in error, I will surely sit in wait for them on Your straight path.","theme":"light"},{"surahNumber":19,"ayahNumber":36,"surahName":"Maryam","arabic":"وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","translation_ar":"وإن ٱلله ربى وربكم فٱعبدوه  هذا صرط مستقيم","translation_es":"[Dijo Jesús:] “Dios es mi Señor y el de ustedes, ¡adórenlo! Ese es el sendero recto”.","translation_en":"[Jesus said], \"And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path.\"","theme":"light"},{"surahNumber":22,"ayahNumber":59,"surahName":"Al-Hajj","arabic":"لَيُدْخِلَنَّهُم مُّدْخَلًۭا يَرْضَوْنَهُۥ ۗ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌۭ","translation_ar":"ليدخلنهم مدخلا يرضونه  وإن ٱلله لعليم حليم","translation_es":"Los introducirá en un Paraíso en el que estarán complacidos. Dios es Conocedor, Tolerante.","translation_en":"He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allah is Knowing and Forbearing.","theme":"mercy"},{"surahNumber":25,"ayahNumber":71,"surahName":"Al-Furqaan","arabic":"وَمَن تَابَ وَعَمِلَ صَٰلِحًۭا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًۭا","translation_ar":"ومن تاب وعمل صلحا فإنه يتوب إلى ٱلله متابا","translation_es":"A quien se arrepienta y haga obras de bien, Dios le aceptará su arrepentimiento.","translation_en":"And he who repents and does righteousness does indeed turn to Allah with [accepted] repentance.","theme":"hope"},{"surahNumber":29,"ayahNumber":11,"surahName":"Al-Ankaboot","arabic":"وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ","translation_ar":"وليعلمن ٱلله ٱلذين ءامنوا وليعلمن ٱلمنفقين","translation_es":"Dios hará evidente quiénes son los que creen y quiénes son los hipócritas.","translation_en":"And Allah will surely make evident those who believe, and He will surely make evident the hypocrites.","theme":"knowledge"},{"surahNumber":33,"ayahNumber":44,"surahName":"Al-Ahzaab","arabic":"تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌۭ ۚ وَأَعَدَّ لَهُمْ أَجْرًۭا كَرِيمًۭا","translation_ar":"تحيتهم يوم يلقونه سلم  وأعد لهم أجرا كريما","translation_es":"Su saludo el día que se encuentren con Él [en el Paraíso] será: “¡Que la paz sea contigo!” Dios les tiene reservada una recompensa generosa.","translation_en":"Their greeting the Day they meet Him will be, \"Peace.\" And He has prepared for them a noble reward.","theme":"mercy"},{"surahNumber":43,"ayahNumber":72,"surahName":"Az-Zukhruf","arabic":"وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ","translation_ar":"وتلك ٱلجنة ٱلتىٓ أورثتموها بما كنتم تعملون","translation_es":"Ese es el Paraíso que han heredado en recompensa por las obras que solían hacer.","translation_en":"And that is Paradise which you are made to inherit for what you used to do.","theme":"paradise"},{"surahNumber":47,"ayahNumber":9,"surahName":"Muhammad","arabic":"ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ","translation_ar":"ذلك بأنهم كرهوا مآ أنزل ٱلله فأحبط أعملهم","translation_es":"porque repudiaron lo que Dios descendió en la revelación, y como consecuencia sus obras se perderán.","translation_en":"That is because they disliked what Allah revealed, so He rendered worthless their deeds.","theme":"creation"},{"surahNumber":2,"ayahNumber":5,"surahName":"Al-Baqara","arabic":"أُو۟لَٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","translation_ar":"أولٓئك على هدى من ربهم  وأولٓئك هم ٱلمفلحون","translation_es":"Esos son los que están en la guía de su Señor y serán los bienaventurados.","translation_en":"Those are upon [right] guidance from their Lord, and it is those who are the successful.","theme":"light"},{"surahNumber":3,"ayahNumber":74,"surahName":"Aal-i-Imraan","arabic":"يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","translation_ar":"يختص برحمته من يشآء  وٱلله ذو ٱلفضل ٱلعظيم","translation_es":"Favorece con Su misericordia a quien Él quiere. Dios es poseedor del favor inmenso.","translation_en":"He selects for His mercy whom He wills. And Allah is the possessor of great bounty.","theme":"creation"},{"surahNumber":12,"ayahNumber":57,"surahName":"Yusuf","arabic":"وَلَأَجْرُ ٱلْءَاخِرَةِ خَيْرٌۭ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ","translation_ar":"ولأجر ٱلءاخرة خير للذين ءامنوا وكانوا يتقون","translation_es":"Pero para los creyentes piadosos la recompensa en la otra vida es superior.","translation_en":"And the reward of the Hereafter is better for those who believed and were fearing Allah.","theme":"deeds"},{"surahNumber":15,"ayahNumber":96,"surahName":"Al-Hijr","arabic":"ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۚ فَسَوْفَ يَعْلَمُونَ","translation_ar":"ٱلذين يجعلون مع ٱلله إلها ءاخر  فسوف يعلمون","translation_es":"de quienes ponen junto a Dios otras deidades, ellos ya pronto sabrán [el castigo que les espera].","translation_en":"Who make [equal] with Allah another deity. But they are going to know.","theme":"knowledge"},{"surahNumber":17,"ayahNumber":65,"surahName":"Al-Israa","arabic":"إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌۭ ۚ وَكَفَىٰ بِرَبِّكَ وَكِيلًۭا","translation_ar":"إن عبادى ليس لك عليهم سلطن  وكفى بربك وكيلا","translation_es":"[Dijo Dios:] “Pero no tienes poder alguno sobre Mis siervos creyentes”. Es suficiente con tu Señor como protector [para quienes se encomiendan a Él].","translation_en":"Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs.","theme":"ease"},{"surahNumber":29,"ayahNumber":66,"surahName":"Al-Ankaboot","arabic":"لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ ۖ فَسَوْفَ يَعْلَمُونَ","translation_ar":"ليكفروا بمآ ءاتينهم وليتمتعوا  فسوف يعلمون","translation_es":"¡Que no agradezcan por cuanto les he concedido y que solo disfruten! ¡Ya verán [la consecuencia de su decisión]!","translation_en":"So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know.","theme":"knowledge"},{"surahNumber":30,"ayahNumber":5,"surahName":"Ar-Room","arabic":"بِنَصْرِ ٱللَّهِ ۚ يَنصُرُ مَن يَشَآءُ ۖ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","translation_ar":"بنصر ٱلله  ينصر من يشآء  وهو ٱلعزيز ٱلرحيم","translation_es":"por la victoria de Dios. Él concede la victoria a quien quiere, Él es el Poderoso, el Misericordioso.","translation_en":"In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.","theme":"victory"},{"surahNumber":39,"ayahNumber":34,"surahName":"Az-Zumar","arabic":"لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ","translation_ar":"لهم ما يشآءون عند ربهم  ذلك جزآء ٱلمحسنين","translation_es":"Ellos tendrán cuanto deseen junto a su Señor. Esa será la recompensa de los que hacen el bien.","translation_en":"They will have whatever they desire with their Lord. That is the reward of the doers of good -","theme":"mercy"},{"surahNumber":44,"ayahNumber":39,"surahName":"Ad-Dukhaan","arabic":"مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ","translation_ar":"ما خلقنهمآ إلا بٱلحق ولكن أكثرهم لا يعلمون","translation_es":"Los creé con un fin justo y verdadero, pero la mayoría de la gente lo ignora.","translation_en":"We did not create them except in truth, but most of them do not know.","theme":"knowledge"},{"surahNumber":45,"ayahNumber":4,"surahName":"Al-Jaathiya","arabic":"وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌۭ لِّقَوْمٍۢ يُوقِنُونَ","translation_ar":"وفى خلقكم وما يبث من دآبة ءايت لقوم يوقنون","translation_es":"También en la creación de ustedes y en la diseminación de los animales [en la faz de la Tierra] hay signos para quienes tienen certeza.","translation_en":"And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].","theme":"creation"},{"surahNumber":2,"ayahNumber":77,"surahName":"Al-Baqara","arabic":"أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ","translation_ar":"أولا يعلمون أن ٱلله يعلم ما يسرون وما يعلنون","translation_es":"¿Es que no saben que Dios conoce lo que ocultan y lo que hacen público?","translation_en":"But do they not know that Allah knows what they conceal and what they declare?","theme":"knowledge"},{"surahNumber":2,"ayahNumber":163,"surahName":"Al-Baqara","arabic":"وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ","translation_ar":"وإلهكم إله وحد  لآ إله إلا هو ٱلرحمن ٱلرحيم","translation_es":"Su Dios es un Dios Único, no hay divinidad [con derecho a ser","translation_en":"And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful.","theme":"mercy"},{"surahNumber":3,"ayahNumber":76,"surahName":"Aal-i-Imraan","arabic":"بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ","translation_ar":"بلى من أوفى بعهده وٱتقى فإن ٱلله يحب ٱلمتقين","translation_es":"Por el contrario, quien cumpla su promesa y tenga temor de Dios, sepa que Dios ama a los piadosos.","translation_en":"But yes, whoever fulfills his commitment and fears Allah - then indeed, Allah loves those who fear Him.","theme":"light"},{"surahNumber":4,"ayahNumber":96,"surahName":"An-Nisaa","arabic":"دَرَجَٰتٍۢ مِّنْهُ وَمَغْفِرَةًۭ وَرَحْمَةًۭ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًا","translation_ar":"درجت منه ومغفرة ورحمة  وكان ٱلله غفورا رحيما","translation_es":"Son grados que Él concede, junto con Su perdón y misericordia. Dios es Indulgente y Misericordioso.","translation_en":"Degrees [of high position] from Him and forgiveness and mercy. And Allah is ever Forgiving and Merciful.","theme":"hope"},{"surahNumber":6,"ayahNumber":149,"surahName":"Al-An'aam","arabic":"قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ","translation_ar":"قل فلله ٱلحجة ٱلبلغة  فلو شآء لهدىكم أجمعين","translation_es":"Di: “Dios posee la Verdad absoluta, y si hubiera querido los habría guiado a todos”.","translation_en":"Say, \"With Allah is the far-reaching argument. If He had willed, He would have guided you all.\"","theme":"light"},{"surahNumber":22,"ayahNumber":16,"surahName":"Al-Hajj","arabic":"وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍۢ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ","translation_ar":"وكذلك أنزلنه ءايت بينت وأن ٱلله يهدى من يريد","translation_es":"Así [como en las revelaciones anteriores] he revelado versículos claros, porque Dios guía a quien quiere.","translation_en":"And thus have We sent the Qur'an down as verses of clear evidence and because Allah guides whom He intends.","theme":"light"},{"surahNumber":22,"ayahNumber":32,"surahName":"Al-Hajj","arabic":"ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ","translation_ar":"ذلك ومن يعظم شعٓئر ٱلله فإنها من تقوى ٱلقلوب","translation_es":"Sepan que respetar los ritos de Dios dimana de la piedad que hay en los corazones.","translation_en":"That [is so]. And whoever honors the symbols of Allah - indeed, it is from the piety of hearts.","theme":"light"},{"surahNumber":23,"ayahNumber":29,"surahName":"Al-Muminoon","arabic":"وَقُل رَّبِّ أَنزِلْنِى مُنزَلًۭا مُّبَارَكًۭا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ","translation_ar":"وقل رب أنزلنى منزلا مباركا وأنت خير ٱلمنزلين","translation_es":"Y di: “¡Señor mío! Hazme llegar a un destino bendito, pues Tú eres Quien mejor hace llegar a destino”.","translation_en":"And say, 'My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].' \"","theme":"creation"},{"surahNumber":31,"ayahNumber":8,"surahName":"Luqman","arabic":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ٱلنَّعِيمِ","translation_ar":"إن ٱلذين ءامنوا وعملوا ٱلصلحت لهم جنت ٱلنعيم","translation_es":"En cambio, quienes crean y hagan obras de bien serán recompensados con los Jardines de las Delicias.","translation_en":"Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure.","theme":"paradise"},{"surahNumber":34,"ayahNumber":25,"surahName":"Saba","arabic":"قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ","translation_ar":"قل لا تسٔلون عمآ أجرمنا ولا نسٔل عما تعملون","translation_es":"Diles: “Ustedes no serán interrogados por nuestras faltas, ni nosotros seremos interrogados por las suyas”.","translation_en":"Say, \"You will not be asked about what we committed, and we will not be asked about what you do.\"","theme":"deeds"},{"surahNumber":38,"ayahNumber":76,"surahName":"Saad","arabic":"قَالَ أَنَا۠ خَيْرٌۭ مِّنْهُ ۖ خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ","translation_ar":"قال أنا خير منه  خلقتنى من نار وخلقته من طين","translation_es":"Dijo [Iblís]: “Yo soy superior a él. A mí me creaste de fuego, mientras que a él lo creaste de barro”.","translation_en":"He said, \"I am better than him. You created me from fire and created him from clay.\"","theme":"creation"},{"surahNumber":42,"ayahNumber":35,"surahName":"Ash-Shura","arabic":"وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍۢ","translation_ar":"ويعلم ٱلذين يجدلون فىٓ ءايتنا ما لهم من محيص","translation_es":"Ya sabrán quienes disputan sobre Mis signos que no tendrán escapatoria.","translation_en":"And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.","theme":"knowledge"},{"surahNumber":43,"ayahNumber":43,"surahName":"Az-Zukhruf","arabic":"فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ ۖ إِنَّكَ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"فٱستمسك بٱلذىٓ أوحى إليك  إنك على صرط مستقيم","translation_es":"Aférrate a lo que te fue revelado, tú estás en el sendero recto.","translation_en":"So adhere to that which is revealed to you. Indeed, you are on a straight path.","theme":"light"},{"surahNumber":44,"ayahNumber":17,"surahName":"Ad-Dukhaan","arabic":"۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌۭ كَرِيمٌ","translation_ar":" ولقد فتنا قبلهم قوم فرعون وجآءهم رسول كريم","translation_es":"Antes de ellos probé al pueblo del Faraón, cuando se les presentó un Mensajero noble,","translation_en":"And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,","theme":"mercy"},{"surahNumber":6,"ayahNumber":16,"surahName":"Al-An'aam","arabic":"مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍۢ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ","translation_ar":"من يصرف عنه يومئذ فقد رحمه  وذلك ٱلفوز ٱلمبين","translation_es":"Quien sea eximido [del castigo] ese día será porque Dios se apiadó de él, y ese será un triunfo evidente.","translation_en":"He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.","theme":"paradise"},{"surahNumber":12,"ayahNumber":98,"surahName":"Yusuf","arabic":"قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","translation_ar":"قال سوف أستغفر لكم ربىٓ  إنه هو ٱلغفور ٱلرحيم","translation_es":"Respondió: “Pediré a mi Señor que los perdone, Él es el Absolvedor, el Misericordioso”.","translation_en":"He said, \"I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful.\"","theme":"hope"},{"surahNumber":12,"ayahNumber":104,"surahName":"Yusuf","arabic":"وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ","translation_ar":"وما تسٔلهم عليه من أجر  إن هو إلا ذكر للعلمين","translation_es":"Tú no pides remuneración alguna por transmitir el Mensaje, que está dirigido a toda la humanidad.","translation_en":"And you do not ask of them for it any payment. It is not except a reminder to the worlds.","theme":"deeds"},{"surahNumber":19,"ayahNumber":67,"surahName":"Maryam","arabic":"أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًۭٔا","translation_ar":"أولا يذكر ٱلإنسن أنا خلقنه من قبل ولم يك شئا","translation_es":"¿Acaso no recuerda el ser humano que lo creé por primera vez cuando no era nada?","translation_en":"Does man not remember that We created him before, while he was nothing?","theme":"creation"},{"surahNumber":21,"ayahNumber":10,"surahName":"Al-Anbiyaa","arabic":"لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًۭا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ","translation_ar":"لقد أنزلنآ إليكم كتبا فيه ذكركم  أفلا تعقلون","translation_es":"Les he revelado un Libro en el que hay una amonestación para ustedes. ¿Cómo es que no reflexionan?","translation_en":"We have certainly sent down to you a Book in which is your mention. Then will you not reason?","theme":"creation"},{"surahNumber":25,"ayahNumber":43,"surahName":"Al-Furqaan","arabic":"أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا","translation_ar":"أرءيت من ٱتخذ إلهه هوىه أفأنت تكون عليه وكيلا","translation_es":"¿Has visto a esos que toman su propio ego como su dios? Tú no eres responsable por sus acciones.","translation_en":"Have you seen the one who takes as his god his own desire? Then would you be responsible for him?","theme":"victory"},{"surahNumber":34,"ayahNumber":51,"surahName":"Saba","arabic":"وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍۢ قَرِيبٍۢ","translation_ar":"ولو ترىٓ إذ فزعوا فلا فوت وأخذوا من مكان قريب","translation_es":"¡Si vieras [¡oh, Mujámmad!] cuando [los incrédulos] se aterroricen [al ver el castigo que les aguarda] y no tengan forma de escapar! Serán tomados desde un lugar cercano [y arrojados al Fuego].","translation_en":"And if you could see when they are terrified but there is no escape, and they will be seized from a place nearby.","theme":"hope"},{"surahNumber":43,"ayahNumber":87,"surahName":"Az-Zukhruf","arabic":"وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ","translation_ar":"ولئن سألتهم من خلقهم ليقولن ٱلله  فأنى يؤفكون","translation_es":"Si les preguntas [a los que se niegan a creer] quién los ha creado, te responderán: “¡Dios!” ¿Cómo entonces se descarrían?27","translation_en":"And if you asked them who created them, they would surely say, \"Allah.\" So how are they deluded?","theme":"creation"},{"surahNumber":73,"ayahNumber":9,"surahName":"Al-Muzzammil","arabic":"رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًۭا","translation_ar":"رب ٱلمشرق وٱلمغرب لآ إله إلا هو فٱتخذه وكيلا","translation_es":"Él es el Señor del oriente y del occidente. No hay nada ni nadie con derecho a ser adorado salvo Él. Tómalo como tu protector.","translation_en":"[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.","theme":"victory"},{"surahNumber":5,"ayahNumber":98,"surahName":"Al-Maaida","arabic":"ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"ٱعلموٓا أن ٱلله شديد ٱلعقاب وأن ٱلله غفور رحيم","translation_es":"Sepan que Dios es severo en el castigo, pero también es Perdonador, Misericordioso.","translation_en":"Know that Allah is severe in penalty and that Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":11,"ayahNumber":30,"surahName":"Hud","arabic":"وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ ۚ أَفَلَا تَذَكَّرُونَ","translation_ar":"ويقوم من ينصرنى من ٱلله إن طردتهم  أفلا تذكرون","translation_es":"¡Oh, pueblo mío! ¿Quién me protegerá de Dios si despreciara [a los pobres y débiles]? ¿Es que no recapacitan?","translation_en":"And O my people, who would protect me from Allah if I drove them away? Then will you not be reminded?","theme":"victory"},{"surahNumber":15,"ayahNumber":3,"surahName":"Al-Hijr","arabic":"ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ","translation_ar":"ذرهم يأكلوا ويتمتعوا ويلههم ٱلأمل  فسوف يعلمون","translation_es":"Déjalos que coman, que disfruten y sean seducidos por el apego a esta vida mundanal, que ya sabrán.","translation_en":"Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know.","theme":"knowledge"},{"surahNumber":16,"ayahNumber":5,"surahName":"An-Nahl","arabic":"وَٱلْأَنْعَٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌۭ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ","translation_ar":"وٱلأنعم خلقها  لكم فيها دفء ومنفع ومنها تأكلون","translation_es":"Dios creó a los ganados, de los cuales ustedes obtienen sus abrigos y otros beneficios, y también de ellos se alimentan.","translation_en":"And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.","theme":"creation"},{"surahNumber":23,"ayahNumber":115,"surahName":"Al-Muminoon","arabic":"أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ","translation_ar":"أفحسبتم أنما خلقنكم عبثا وأنكم إلينا لا ترجعون","translation_es":"¿Acaso creían que los creé sin ningún sentido? ¿Creían que no iban a comparecer ante Mí?","translation_en":"Then did you think that We created you uselessly and that to Us you would not be returned?\"","theme":"creation"},{"surahNumber":24,"ayahNumber":10,"surahName":"An-Noor","arabic":"وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ","translation_ar":"ولولا فضل ٱلله عليكم ورحمته وأن ٱلله تواب حكيم","translation_es":"Si no fuese por la gracia de Dios y Su misericordia con ustedes, y porque Dios acepta el arrepentimiento y es Sabio [les hubiera hecho descender el castigo que imprecaban].","translation_en":"And if not for the favor of Allah upon you and His mercy... and because Allah is Accepting of repentance and Wise.","theme":"creation"},{"surahNumber":26,"ayahNumber":197,"surahName":"Ash-Shu'araa","arabic":"أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ","translation_ar":"أولم يكن لهم ءاية أن يعلمه علمٓؤا بنىٓ إسرٓءيل","translation_es":"¿Acaso no es prueba suficiente que lo reconozcan los sabios de los Hijos de Israel?","translation_en":"And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?","theme":"knowledge"},{"surahNumber":32,"ayahNumber":7,"surahName":"As-Sajda","arabic":"ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ ۖ وَبَدَأَ خَلْقَ ٱلْإِنسَٰنِ مِن طِينٍۢ","translation_ar":"ٱلذىٓ أحسن كل شىء خلقه  وبدأ خلق ٱلإنسن من طين","translation_es":"quien perfeccionó todo lo que ha creado, y comenzó la creación del ser humano del barro.","translation_en":"Who perfected everything which He created and began the creation of man from clay.","theme":"creation"},{"surahNumber":35,"ayahNumber":30,"surahName":"Faatir","arabic":"لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ ۚ إِنَّهُۥ غَفُورٌۭ شَكُورٌۭ","translation_ar":"ليوفيهم أجورهم ويزيدهم من فضلهٓ  إنه غفور شكور","translation_es":"Dios les retribuirá por sus obras y les concederá aún más de Su bendición, porque Él es Absolvedor, Recompensador.","translation_en":"That He may give them in full their rewards and increase for them of His bounty. Indeed, He is Forgiving and Appreciative.","theme":"hope"},{"surahNumber":50,"ayahNumber":11,"surahName":"Qaaf","arabic":"رِّزْقًۭا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ ٱلْخُرُوجُ","translation_ar":"رزقا للعباد  وأحيينا به بلدة ميتا  كذلك ٱلخروج","translation_es":"como sustento para los siervos. Así como doy vida con la lluvia a la tierra árida, así los resucitaré.","translation_en":"As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection.","theme":"creation"},{"surahNumber":50,"ayahNumber":15,"surahName":"Qaaf","arabic":"أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍۢ مِّنْ خَلْقٍۢ جَدِيدٍۢ","translation_ar":"أفعيينا بٱلخلق ٱلأول  بل هم فى لبس من خلق جديد","translation_es":"¿Acaso fallé al crearlos por primera vez? Pero a pesar de eso dudan de una nueva creación.","translation_en":"Did We fail in the first creation? But they are in confusion over a new creation.","theme":"creation"},{"surahNumber":7,"ayahNumber":140,"surahName":"Al-A'raaf","arabic":"قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًۭا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ","translation_ar":"قال أغير ٱلله أبغيكم إلها وهو فضلكم على ٱلعلمين","translation_es":"Dijo: “¿Cómo podría admitir que ustedes adoren ídolos en vez de Dios, siendo que Él los distinguió entre sus contemporáneos?","translation_en":"He said, \"Is it other than Allah I should desire for you as a god while He has preferred you over the worlds?\"","theme":"creation"},{"surahNumber":7,"ayahNumber":182,"surahName":"Al-A'raaf","arabic":"وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ","translation_ar":"وٱلذين كذبوا بٔايتنا سنستدرجهم من حيث لا يعلمون","translation_es":"A quienes desmientan Mis signos los degradaré paulatinamente sin que puedan darse cuenta.","translation_en":"But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know.","theme":"knowledge"},{"surahNumber":9,"ayahNumber":76,"surahName":"At-Tawba","arabic":"فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ","translation_ar":"فلمآ ءاتىهم من فضله بخلوا به وتولوا وهم معرضون","translation_es":"Pero cuando Dios los bendijo con bienes materiales, se mostraron avaros y le dieron la espalda con desdén.","translation_en":"But when he gave them from His bounty, they were stingy with it and turned away while they refused.","theme":"creation"},{"surahNumber":11,"ayahNumber":90,"surahName":"Hud","arabic":"وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌۭ وَدُودٌۭ","translation_ar":"وٱستغفروا ربكم ثم توبوٓا إليه  إن ربى رحيم ودود","translation_es":"Pidan perdón a su Señor y arrepiéntanse, porque mi Señor es Misericordioso, Afectuoso”.","translation_en":"And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate.\"","theme":"mercy"},{"surahNumber":20,"ayahNumber":110,"surahName":"Taa-Haa","arabic":"يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًۭا","translation_ar":"يعلم ما بين أيديهم وما خلفهم ولا يحيطون به علما","translation_es":"Dios bien conoce el pasado y el futuro, mientras que ellos nunca podrán alcanzar este conocimiento.","translation_en":"Allah knows what is [presently] before them and what will be after them, but they do not encompass it in knowledge.","theme":"knowledge"},{"surahNumber":21,"ayahNumber":96,"surahName":"Al-Anbiyaa","arabic":"حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍۢ يَنسِلُونَ","translation_ar":"حتىٓ إذا فتحت يأجوج ومأجوج وهم من كل حدب ينسلون","translation_es":"[Cuando se aproxime el Último Día] serán liberados Gog y Magog, y se precipitarán desde todas las laderas [devastando cuanto encuentren a su paso].","translation_en":"Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend","theme":"victory"},{"surahNumber":22,"ayahNumber":50,"surahName":"Al-Hajj","arabic":"فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ","translation_ar":"فٱلذين ءامنوا وعملوا ٱلصلحت لهم مغفرة ورزق كريم","translation_es":"Los que creyeron y obraron rectamente obtendrán el perdón y un sustento generoso.","translation_en":"And those who have believed and done righteous deeds - for them is forgiveness and noble provision.","theme":"mercy"},{"surahNumber":38,"ayahNumber":86,"surahName":"Saad","arabic":"قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍۢ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ","translation_ar":"قل مآ أسٔلكم عليه من أجر ومآ أنا من ٱلمتكلفين","translation_es":"Diles [¡oh, Mujámmad!]: “Yo no les pido ninguna remuneración a cambio [de transmitirles el Mensaje], ni soy de los que inventan mentiras.","translation_en":"Say, [O Muhammad], \"I do not ask you for the Qur'an any payment, and I am not of the pretentious","theme":"deeds"},{"surahNumber":72,"ayahNumber":2,"surahName":"Al-Jinn","arabic":"يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًۭا","translation_ar":"يهدىٓ إلى ٱلرشد فٔامنا به  ولن نشرك بربنآ أحدا","translation_es":"que guía al sendero recto. Creemos en la recitación y no caeremos en la idolatría adorando a otro que Dios.","translation_en":"It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone.","theme":"light"},{"surahNumber":4,"ayahNumber":132,"surahName":"An-Nisaa","arabic":"وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا","translation_ar":"ولله ما فى ٱلسموت وما فى ٱلأرض  وكفى بٱلله وكيلا","translation_es":"A Dios pertenece cuanto hay en los cielos y en la Tierra. Dios es Quien vela por ellos.","translation_en":"And to Allah belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.","theme":"ease"},{"surahNumber":5,"ayahNumber":74,"surahName":"Al-Maaida","arabic":"أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"أفلا يتوبون إلى ٱلله ويستغفرونه  وٱلله غفور رحيم","translation_es":"¿Acaso no van a arrepentirse y pedir perdón a Dios? Dios es Perdonador, Misericordioso.","translation_en":"So will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":15,"ayahNumber":14,"surahName":"Al-Hijr","arabic":"وَلَوْ فَتَحْنَا عَلَيْهِم بَابًۭا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ","translation_ar":"ولو فتحنا عليهم بابا من ٱلسمآء فظلوا فيه يعرجون","translation_es":"Y aunque les abriera una puerta en el cielo por la que pudieran ascender [y contemplar a los ángeles] no creerían.","translation_en":"And [even] if We opened to them a gate from the heaven and they continued therein to ascend,","theme":"victory"},{"surahNumber":19,"ayahNumber":24,"surahName":"Maryam","arabic":"فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّۭا","translation_ar":"فنادىها من تحتهآ ألا تحزنى قد جعل ربك تحتك سريا","translation_es":"Entonces [el ángel] la llamó desde abajo [del valle]: “No estés triste, tu Señor ha hecho fluir debajo de ti un arroyo.","translation_en":"But he called her from below her, \"Do not grieve; your Lord has provided beneath you a stream.","theme":"sadness"},{"surahNumber":26,"ayahNumber":118,"surahName":"Ash-Shu'araa","arabic":"فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًۭا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ","translation_ar":"فٱفتح بينى وبينهم فتحا ونجنى ومن معى من ٱلمؤمنين","translation_es":"Juzga definitivamente entre ellos y yo. Salva a los creyentes que están conmigo, y a mí con ellos”.","translation_en":"Then judge between me and them with decisive judgement and save me and those with me of the believers.\"","theme":"victory"},{"surahNumber":42,"ayahNumber":19,"surahName":"Ash-Shura","arabic":"ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ","translation_ar":"ٱلله لطيف بعباده يرزق من يشآء  وهو ٱلقوى ٱلعزيز","translation_es":"Dios es Bondadoso con Sus siervos, sustenta a quien quiere. Él es el Fuerte, el Poderoso.","translation_en":"Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.","theme":"mercy"},{"surahNumber":72,"ayahNumber":25,"surahName":"Al-Jinn","arabic":"قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌۭ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا","translation_ar":"قل إن أدرىٓ أقريب ما توعدون أم يجعل له ربىٓ أمدا","translation_es":"Diles: “No sé si está cerca aquello con que se los ha advertido, o si mi Señor le ha fijado un plazo distante.","translation_en":"Say, \"I do not know if what you are promised is near or if my Lord will grant for it a [long] period.\"","theme":"hope"},{"surahNumber":84,"ayahNumber":25,"surahName":"Al-Inshiqaaq","arabic":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ","translation_ar":"إلا ٱلذين ءامنوا وعملوا ٱلصلحت لهم أجر غير ممنون","translation_es":"salvo a quienes crean y obren rectamente, porque ellos recibirán una recompensa inagotable.","translation_en":"Except for those who believe and do righteous deeds. For them is a reward uninterrupted.","theme":"deeds"},{"surahNumber":3,"ayahNumber":115,"surahName":"Aal-i-Imraan","arabic":"وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍۢ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ","translation_ar":"وما يفعلوا من خير فلن يكفروه  وٱلله عليم بٱلمتقين","translation_es":"El bien que hayan hecho antes de adoptar el Islam no será desmerecido. Dios conoce bien a los piadosos.","translation_en":"And whatever good they do - never will it be removed from them. And Allah is Knowing of the righteous.","theme":"light"},{"surahNumber":3,"ayahNumber":139,"surahName":"Aal-i-Imraan","arabic":"وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ","translation_ar":"ولا تهنوا ولا تحزنوا وأنتم ٱلأعلون إن كنتم مؤمنين","translation_es":"No se desanimen ni entristezcan, porque los que obtendrán el éxito finalmente serán los creyentes.","translation_en":"So do not weaken and do not grieve, and you will be superior if you are [true] believers.","theme":"sadness"},{"surahNumber":6,"ayahNumber":126,"surahName":"Al-An'aam","arabic":"وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًۭا ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَذَّكَّرُونَ","translation_ar":"وهذا صرط ربك مستقيما  قد فصلنا ٱلءايت لقوم يذكرون","translation_es":"Este es el sendero recto de tu Señor. He hecho claro el mensaje para quienes reflexionan.","translation_en":"And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.","theme":"light"},{"surahNumber":18,"ayahNumber":43,"surahName":"Al-Kahf","arabic":"وَلَمْ تَكُن لَّهُۥ فِئَةٌۭ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا","translation_ar":"ولم تكن له فئة ينصرونه من دون ٱلله وما كان منتصرا","translation_es":"No tuvo quien pudiera salvarlo del designio de Dios, ni siquiera pudo defenderse a sí mismo.","translation_en":"And there was for him no company to aid him other than Allah, nor could he defend himself.","theme":"victory"},{"surahNumber":26,"ayahNumber":7,"surahName":"Ash-Shu'araa","arabic":"أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۢ كَرِيمٍ","translation_ar":"أولم يروا إلى ٱلأرض كم أنبتنا فيها من كل زوج كريم","translation_es":"¿Acaso no observan la Tierra y reparan sobre cuántas especies nobles he creado en ella?","translation_en":"Did they not look at the earth - how much We have produced therein from every noble kind?","theme":"mercy"},{"surahNumber":40,"ayahNumber":53,"surahName":"Ghafir","arabic":"وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ","translation_ar":"ولقد ءاتينا موسى ٱلهدى وأورثنا بنىٓ إسرٓءيل ٱلكتب","translation_es":"Concedí a Moisés la guía, e hice que los Hijos de Israel heredaran el Libro [de la Tora],","translation_en":"And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture","theme":"light"},{"surahNumber":43,"ayahNumber":40,"surahName":"Az-Zukhruf","arabic":"أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍۢ مُّبِينٍۢ","translation_ar":"أفأنت تسمع ٱلصم أو تهدى ٱلعمى ومن كان فى ضلل مبين","translation_es":"¿Acaso puedes hacer tú [¡oh, Mujámmad!] oír a [quienes se comportan como] los sordos, o guiar a los ciegos [de corazón] y a aquel que está en un claro extravío?","translation_en":"Then will you make the deaf hear, [O Muhammad], or guide the blind or he who is in clear error?","theme":"light"},{"surahNumber":51,"ayahNumber":16,"surahName":"Adh-Dhaariyat","arabic":"ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ","translation_ar":"ءاخذين مآ ءاتىهم ربهم  إنهم كانوا قبل ذلك محسنين","translation_es":"Disfrutarán lo que Su Señor les conceda, porque en la vida mundanal hacían el bien,","translation_en":"Accepting what their Lord has given them. Indeed, they were before that doers of good.","theme":"mercy"},{"surahNumber":3,"ayahNumber":96,"surahName":"Aal-i-Imraan","arabic":"إِنَّ أَوَّلَ بَيْتٍۢ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًۭا وَهُدًۭى لِّلْعَٰلَمِينَ","translation_ar":"إن أول بيت وضع للناس للذى ببكة مباركا وهدى للعلمين","translation_es":"El primer templo erigido para los seres humanos es el de Bakkah [la Ka‘bah], en él hay bendición y guía para la humanidad.","translation_en":"Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds.","theme":"light"},{"surahNumber":6,"ayahNumber":103,"surahName":"Al-An'aam","arabic":"لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ","translation_ar":"لا تدركه ٱلأبصر وهو يدرك ٱلأبصر  وهو ٱللطيف ٱلخبير","translation_es":"La vista [de los seres humanos] no puede abarcarlo, pero Él sí ve [a todos Sus siervos]. Él es el Sutil y el Conocedor.","translation_en":"Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Acquainted.","theme":"mercy"},{"surahNumber":8,"ayahNumber":22,"surahName":"Al-Anfaal","arabic":"۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ","translation_ar":" إن شر ٱلدوآب عند ٱلله ٱلصم ٱلبكم ٱلذين لا يعقلون","translation_es":"Las peores criaturas para Dios son los sordos [que no quieren oír la Verdad] y los mudos [que no quieren atestiguar la Verdad], los que no razonan.","translation_en":"Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.","theme":"knowledge"},{"surahNumber":16,"ayahNumber":18,"surahName":"An-Nahl","arabic":"وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌۭ رَّحِيمٌۭ","translation_ar":"وإن تعدوا نعمة ٱلله لا تحصوهآ  إن ٱلله لغفور رحيم","translation_es":"Si intentaran contar las gracias de Dios no podrían enumerarlas. Dios es Absolvedor, Misericordioso.","translation_en":"And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":16,"ayahNumber":99,"surahName":"An-Nahl","arabic":"إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ","translation_ar":"إنه ليس له سلطن على ٱلذين ءامنوا وعلى ربهم يتوكلون","translation_es":"El demonio no tiene poder sobre los creyentes que se encomiendan a su Señor.","translation_en":"Indeed, there is for him no authority over those who have believed and rely upon their Lord.","theme":"victory"},{"surahNumber":17,"ayahNumber":84,"surahName":"Al-Israa","arabic":"قُلْ كُلٌّۭ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًۭا","translation_ar":"قل كل يعمل على شاكلته فربكم أعلم بمن هو أهدى سبيلا","translation_es":"Diles: “Que cada uno obre como le plazca, pero sepan que su Señor conoce a quien está mejor encaminado”.","translation_en":"Say, \"Each works according to his manner, but your Lord is most knowing of who is best guided in way.\"","theme":"light"},{"surahNumber":2,"ayahNumber":66,"surahName":"Al-Baqara","arabic":"فَجَعَلْنَٰهَا نَكَٰلًۭا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ","translation_ar":"فجعلنها نكلا لما بين يديها وما خلفها وموعظة للمتقين","translation_es":"Hice de ello un escarmiento para sus contemporáneos y descendientes, y motivo de reflexión para los que temen devocionalmente a Dios.","translation_en":"And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allah.","theme":"light"},{"surahNumber":3,"ayahNumber":107,"surahName":"Aal-i-Imraan","arabic":"وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ","translation_ar":"وأما ٱلذين ٱبيضت وجوههم ففى رحمة ٱلله هم فيها خلدون","translation_es":"En cuanto a aquellos cuyos rostros estén radiantes, estarán en la misericordia de Dios eternamente.","translation_en":"But as for those whose faces will turn white, [they will be] within the mercy of Allah. They will abide therein eternally.","theme":"mercy"},{"surahNumber":4,"ayahNumber":50,"surahName":"An-Nisaa","arabic":"ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَكَفَىٰ بِهِۦٓ إِثْمًۭا مُّبِينًا","translation_ar":"ٱنظر كيف يفترون على ٱلله ٱلكذب  وكفى بهٓ إثما مبينا","translation_es":"Observa cómo inventan mentiras y las atribuyen a Dios. Eso es en sí mismo un pecado evidente.","translation_en":"Look how they invent about Allah untruth, and sufficient is that as a manifest sin.","theme":"ease"},{"surahNumber":4,"ayahNumber":99,"surahName":"An-Nisaa","arabic":"فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًۭا","translation_ar":"فأولٓئك عسى ٱلله أن يعفو عنهم  وكان ٱلله عفوا غفورا","translation_es":"A ellos Dios los perdonará, porque Dios es Remisorio, Indulgente.","translation_en":"For those it is expected that Allah will pardon them, and Allah is ever Pardoning and Forgiving.","theme":"hope"},{"surahNumber":6,"ayahNumber":105,"surahName":"Al-An'aam","arabic":"وَكَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍۢ يَعْلَمُونَ","translation_ar":"وكذلك نصرف ٱلءايت وليقولوا درست ولنبينه لقوم يعلمون","translation_es":"Así es como evidencio los signos, aunque [los que se niegan a creer] dicen: “Lo has aprendido de otros”. Pero lo hago claro para la gente que tiene conocimiento.","translation_en":"And thus do We diversify the verses so the disbelievers will say, \"You have studied,\" and so We may make the Qur'an clear for a people who know.","theme":"knowledge"},{"surahNumber":7,"ayahNumber":52,"surahName":"Al-A'raaf","arabic":"وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍۢ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ","translation_ar":"ولقد جئنهم بكتب فصلنه على علم هدى ورحمة لقوم يؤمنون","translation_es":"Les envié el Libro, en el que detallé todas las cosas con sabiduría, como guía y misericordia para la gente que cree.","translation_en":"And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe.","theme":"mercy"},{"surahNumber":9,"ayahNumber":21,"surahName":"At-Tawba","arabic":"يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍۢ مِّنْهُ وَرِضْوَٰنٍۢ وَجَنَّٰتٍۢ لَّهُمْ فِيهَا نَعِيمٌۭ مُّقِيمٌ","translation_ar":"يبشرهم ربهم برحمة منه ورضون وجنت لهم فيها نعيم مقيم","translation_es":"Su Señor les albricia [que serán recompensados] con Su misericordia, Su complacencia, y con jardines donde gozarán de delicias inagotables.","translation_en":"Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.","theme":"mercy"},{"surahNumber":16,"ayahNumber":122,"surahName":"An-Nahl","arabic":"وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةًۭ ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ","translation_ar":"وءاتينه فى ٱلدنيا حسنة  وإنه فى ٱلءاخرة لمن ٱلصلحين","translation_es":"Le concedí en la vida mundanal todo lo bueno, y en la otra vida estará con los justos.","translation_en":"And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous.","theme":"deeds"},{"surahNumber":26,"ayahNumber":109,"surahName":"Ash-Shu'araa","arabic":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ","translation_ar":"ومآ أسٔلكم عليه من أجر  إن أجرى إلا على رب ٱلعلمين","translation_es":"No les pido remuneración a cambio [de transmitirles el Mensaje]. Mi recompensa me la dará el Señor del Universo.","translation_en":"And I do not ask you for it any payment. My payment is only from the Lord of the worlds.","theme":"deeds"},{"surahNumber":28,"ayahNumber":41,"surahName":"Al-Qasas","arabic":"وَجَعَلْنَٰهُمْ أَئِمَّةًۭ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ","translation_ar":"وجعلنهم أئمة يدعون إلى ٱلنار  ويوم ٱلقيمة لا ينصرون","translation_es":"Hice que ellos [en esta vida] fueran líderes, pero conducían [a la gente al] Infierno. El Día de la Resurrección no serán socorridos.","translation_en":"And We made them leaders inviting to the Fire, and on the Day of Resurrection they will not be helped.","theme":"victory"},{"surahNumber":42,"ayahNumber":30,"surahName":"Ash-Shura","arabic":"وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍۢ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍۢ","translation_ar":"ومآ أصبكم من مصيبة فبما كسبت أيديكم ويعفوا عن كثير","translation_es":"Si los aflige una desgracia, es consecuencia de [los pecados] que sus propias manos han cometido, a pesar de que Dios les perdona muchas faltas [por Su gracia].","translation_en":"And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.","theme":"mercy"},{"surahNumber":46,"ayahNumber":14,"surahName":"Al-Ahqaf","arabic":"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ","translation_ar":"أولٓئك أصحب ٱلجنة خلدين فيها جزآء بما كانوا يعملون","translation_es":"porque serán los compañeros del Paraíso, en el que vivirán por toda la eternidad como recompensa por sus obras.","translation_en":"Those are the companions of Paradise, abiding eternally therein as reward for what they used to do.","theme":"paradise"},{"surahNumber":61,"ayahNumber":13,"surahName":"As-Saff","arabic":"وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌۭ مِّنَ ٱللَّهِ وَفَتْحٌۭ قَرِيبٌۭ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ","translation_ar":"وأخرى تحبونها  نصر من ٱلله وفتح قريب  وبشر ٱلمؤمنين","translation_es":"También les dará algo que aman: “Su auxilio y una pronta victoria”. Albricia a los creyentes [con la recompensa que recibirán en esta vida y en la otra].","translation_en":"And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.","theme":"hope"},{"surahNumber":2,"ayahNumber":157,"surahName":"Al-Baqara","arabic":"أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌۭ مِّن رَّبِّهِمْ وَرَحْمَةٌۭ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ","translation_ar":"أولٓئك عليهم صلوت من ربهم ورحمة  وأولٓئك هم ٱلمهتدون","translation_es":"A ellos su Señor bendecirá con el perdón y la misericordia, y son los [correctamente] guiados.","translation_en":"Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided.","theme":"mercy"},{"surahNumber":7,"ayahNumber":184,"surahName":"Al-A'raaf","arabic":"أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌۭ مُّبِينٌ","translation_ar":"أولم يتفكروا  ما بصاحبهم من جنة  إن هو إلا نذير مبين","translation_es":"¿Acaso no se dieron cuenta de que su Mensajero no es un demente? Él es un claro amonestador.","translation_en":"Then do they not give thought? There is in their companion [Muhammad] no madness. He is not but a clear warner.","theme":"paradise"},{"surahNumber":16,"ayahNumber":74,"surahName":"An-Nahl","arabic":"فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ ۚ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ","translation_ar":"فلا تضربوا لله ٱلأمثال  إن ٱلله يعلم وأنتم لا تعلمون","translation_es":"No comparen a Dios. Dios sabe y ustedes no saben.","translation_en":"So do not assert similarities to Allah. Indeed, Allah knows and you do not know.","theme":"knowledge"},{"surahNumber":20,"ayahNumber":64,"surahName":"Taa-Haa","arabic":"فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّۭا ۚ وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ","translation_ar":"فأجمعوا كيدكم ثم ٱئتوا صفا  وقد أفلح ٱليوم من ٱستعلى","translation_es":"[Oh, hechiceros de Egipto,] Decidan su plan a seguir, y luego acudan como un solo cuerpo: pues, ¡quien sea superior hoy, ha de conseguir prosperidad!”","translation_en":"So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes.\"","theme":"light"},{"surahNumber":23,"ayahNumber":70,"surahName":"Al-Muminoon","arabic":"أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ ۚ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ","translation_ar":"أم يقولون به جنة  بل جآءهم بٱلحق وأكثرهم للحق كرهون","translation_es":"Afirmaron que era un demente, pero él se presentó con la Verdad, aunque a la mayoría de ellos les disguste la verdad.","translation_en":"Or do they say, \"In him is madness?\" Rather, he brought them the truth, but most of them, to the truth, are averse.","theme":"paradise"},{"surahNumber":25,"ayahNumber":75,"surahName":"Al-Furqaan","arabic":"أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةًۭ وَسَلَٰمًا","translation_ar":"أولٓئك يجزون ٱلغرفة بما صبروا ويلقون فيها تحية وسلما","translation_es":"Ellos serán recompensados con el Paraíso por su perseverancia, y serán recibidos [por los ángeles] con un saludo de paz.","translation_en":"Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace.","theme":"sadness"},{"surahNumber":27,"ayahNumber":89,"surahName":"An-Naml","arabic":"مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌۭ مِّنْهَا وَهُم مِّن فَزَعٍۢ يَوْمَئِذٍ ءَامِنُونَ","translation_ar":"من جآء بٱلحسنة فله خير منها وهم من فزع يومئذ ءامنون","translation_es":"Quien se presente con buenas obras será recompensado con algo mejor [que lo que merezca], y estará a salvo del terror de ese día.","translation_en":"Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe.","theme":"deeds"},{"surahNumber":30,"ayahNumber":7,"surahName":"Ar-Room","arabic":"يَعْلَمُونَ ظَٰهِرًۭا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْءَاخِرَةِ هُمْ غَٰفِلُونَ","translation_ar":"يعلمون ظهرا من ٱلحيوة ٱلدنيا وهم عن ٱلءاخرة هم غفلون","translation_es":"Conocen solo lo superficial de la vida mundanal, y viven despreocupados por la otra vida.","translation_en":"They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.","theme":"knowledge"},{"surahNumber":2,"ayahNumber":3,"surahName":"Al-Baqara","arabic":"ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ","translation_ar":"ٱلذين يؤمنون بٱلغيب ويقيمون ٱلصلوة ومما رزقنهم ينفقون","translation_es":"los que creen en lo oculto, practican la oración, dan caridad de lo que les he proveído,","translation_en":"Who believe in the unseen, establish prayer, and spend out of what We have provided for them,","theme":"deeds"},{"surahNumber":9,"ayahNumber":27,"surahName":"At-Tawba","arabic":"ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"ثم يتوب ٱلله من بعد ذلك على من يشآء  وٱلله غفور رحيم","translation_es":"Luego, Dios perdonó a quienes se arrepintieron [y abrazaron el Islam]. Dios es Absolvedor, Misericordioso.","translation_en":"Then Allah will accept repentance after that for whom He wills; and Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":12,"ayahNumber":22,"surahName":"Yusuf","arabic":"وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translation_ar":"ولما بلغ أشدهٓ ءاتينه حكما وعلما  وكذلك نجزى ٱلمحسنين","translation_es":"Y cuando alcanzó la mayoría de edad, le concedí el discernimiento y la sabiduría [a través de la revelación]. Así es como recompenso a los que hacen el bien.","translation_en":"And when Joseph reached maturity, We gave him judgment and knowledge. And thus We reward the doers of good.","theme":"mercy"},{"surahNumber":17,"ayahNumber":91,"surahName":"Al-Israa","arabic":"أَوْ تَكُونَ لَكَ جَنَّةٌۭ مِّن نَّخِيلٍۢ وَعِنَبٍۢ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا","translation_ar":"أو تكون لك جنة من نخيل وعنب فتفجر ٱلأنهر خللها تفجيرا","translation_es":"o poseas un huerto con palmeras y vides, y hagas brotar en él ríos,","translation_en":"Or [until] you have a garden of palm tress and grapes and make rivers gush forth within them in force [and abundance]","theme":"paradise"},{"surahNumber":23,"ayahNumber":116,"surahName":"Al-Muminoon","arabic":"فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ","translation_ar":"فتعلى ٱلله ٱلملك ٱلحق  لآ إله إلا هو رب ٱلعرش ٱلكريم","translation_es":"¡Exaltado sea Dios! El único Soberano real, no hay otra divinidad salvo Él, Señor del noble Trono.","translation_en":"So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.","theme":"mercy"},{"surahNumber":26,"ayahNumber":51,"surahName":"Ash-Shu'araa","arabic":"إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ","translation_ar":"إنا نطمع أن يغفر لنا ربنا خطينآ أن كنآ أول ٱلمؤمنين","translation_es":"Anhelamos que Nuestro Señor perdone nuestros pecados por haber sido los primeros creyentes [en el Mensaje de Moisés]”.","translation_en":"Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers.\"","theme":"hope"},{"surahNumber":30,"ayahNumber":6,"surahName":"Ar-Room","arabic":"وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","translation_ar":"وعد ٱلله  لا يخلف ٱلله وعده ولكن أكثر ٱلناس لا يعلمون","translation_es":"Esta es la promesa de Dios, y Dios no falta a Su promesa, pero la mayoría de la gente no lo sabe.","translation_en":"[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know.","theme":"knowledge"},{"surahNumber":40,"ayahNumber":70,"surahName":"Ghafir","arabic":"ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا ۖ فَسَوْفَ يَعْلَمُونَ","translation_ar":"ٱلذين كذبوا بٱلكتب وبمآ أرسلنا به رسلنا  فسوف يعلمون","translation_es":"Quienes desmienten el Libro [revelado] y lo que envié junto a Mis Mensajeros ya sabrán [el castigo que les aguarda],","translation_en":"Those who deny the Book and that with which We sent Our messengers - they are going to know,","theme":"knowledge"},{"surahNumber":4,"ayahNumber":45,"surahName":"An-Nisaa","arabic":"وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ ۚ وَكَفَىٰ بِٱللَّهِ وَلِيًّۭا وَكَفَىٰ بِٱللَّهِ نَصِيرًۭا","translation_ar":"وٱلله أعلم بأعدآئكم  وكفى بٱلله وليا وكفى بٱلله نصيرا","translation_es":"Dios conoce bien a los enemigos de ustedes. Dios es suficiente como Protector y Socorredor.","translation_en":"And Allah is most knowing of your enemies; and sufficient is Allah as an ally, and sufficient is Allah as a helper.","theme":"ease"},{"surahNumber":10,"ayahNumber":29,"surahName":"Yunus","arabic":"فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ","translation_ar":"فكفى بٱلله شهيدا بيننا وبينكم إن كنا عن عبادتكم لغفلين","translation_es":"Dios es suficiente como testigo de que no sabíamos que nos adoraban”.","translation_en":"And sufficient is Allah as a witness between us and you that we were of your worship unaware.\"","theme":"ease"},{"surahNumber":32,"ayahNumber":29,"surahName":"As-Sajda","arabic":"قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ","translation_ar":"قل يوم ٱلفتح لا ينفع ٱلذين كفروٓا إيمنهم ولا هم ينظرون","translation_es":"Diles: “Cuando llegue el Día del Juicio ya no les servirá creer a los que rechazaron el Mensaje, ni tendrán otra oportunidad”.","translation_en":"Say, [O Muhammad], \"On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved.\"","theme":"victory"},{"surahNumber":41,"ayahNumber":35,"surahName":"Fussilat","arabic":"وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍۢ","translation_ar":"وما يلقىهآ إلا ٱلذين صبروا وما يلقىهآ إلا ذو حظ عظيم","translation_es":"Esto no lo logran sino los que tienen paciencia; no lo logran sino los que son muy afortunados.","translation_en":"But none is granted it except those who are patient, and none is granted it except one having a great portion [of good].","theme":"sadness"},{"surahNumber":43,"ayahNumber":61,"surahName":"Az-Zukhruf","arabic":"وَإِنَّهُۥ لَعِلْمٌۭ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","translation_ar":"وإنه لعلم للساعة فلا تمترن بها وٱتبعون  هذا صرط مستقيم","translation_es":"[Diles, ¡oh, Mujámmad!:] “[El descenso a la Tierra de] Jesús es una prueba de la [proximidad de la] Hora [del Fin del Mundo]. Así que no duden y síganme, que este es el sendero recto.","translation_en":"And indeed, Jesus will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path.","theme":"light"},{"surahNumber":57,"ayahNumber":11,"surahName":"Al-Hadid","arabic":"مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًۭا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌۭ كَرِيمٌۭ","translation_ar":"من ذا ٱلذى يقرض ٱلله قرضا حسنا فيضعفه له ولهٓ أجر كريم","translation_es":"¿Quién le dará a Dios un préstamo generoso, para que Él se lo multiplique y lo recompense ampliamente?","translation_en":"Who is it that would loan Allah a goodly loan so He will multiply it for him and he will have a noble reward?","theme":"mercy"},{"surahNumber":68,"ayahNumber":44,"surahName":"Al-Qalam","arabic":"فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ","translation_ar":"فذرنى ومن يكذب بهذا ٱلحديث  سنستدرجهم من حيث لا يعلمون","translation_es":"Yo me encargaré de quienes desmienten el Mensaje. Los castigaré sin prisa cuando menos lo esperen.","translation_en":"So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur'an. We will progressively lead them [to punishment] from where they do not know.","theme":"knowledge"},{"surahNumber":90,"ayahNumber":17,"surahName":"Al-Balad","arabic":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","translation_ar":"ثم كان من ٱلذين ءامنوا وتواصوا بٱلصبر وتواصوا بٱلمرحمة","translation_es":"Y ser, además, de los creyentes que se aconsejan mutuamente ser perseverantes [en el camino del esfuerzo y de la fe] y ser misericordiosos [con el prójimo].","translation_en":"And then being among those who believed and advised one another to patience and advised one another to compassion.","theme":"mercy"},{"surahNumber":2,"ayahNumber":37,"surahName":"Al-Baqara","arabic":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍۢ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","translation_ar":"فتلقىٓ ءادم من ربه كلمت فتاب عليه  إنه هو ٱلتواب ٱلرحيم","translation_es":"Pero le fueron inspiradas a Adán unas palabras de su Señor [para que pudiera expresar su arrepentimiento] y Dios aceptó su arrepentimiento, porque Él es el Indulgente, el Misericordioso.","translation_en":"Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of repentance, the Merciful.","theme":"mercy"},{"surahNumber":2,"ayahNumber":78,"surahName":"Al-Baqara","arabic":"وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ","translation_ar":"ومنهم أميون لا يعلمون ٱلكتب إلآ أمانى وإن هم إلا يظنون","translation_es":"Entre ellos hay iletrados sin conocimiento que no conocen el Libro, que siguen solo sus propios deseos y no hacen sino conjeturar.","translation_en":"And among them are unlettered ones who do not know the Scripture except in wishful thinking, but they are only assuming.","theme":"knowledge"},{"surahNumber":3,"ayahNumber":128,"surahName":"Aal-i-Imraan","arabic":"لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ","translation_ar":"ليس لك من ٱلأمر شىء أو يتوب عليهم أو يعذبهم فإنهم ظلمون","translation_es":"No es asunto tuyo [oh, Mujámmad] si Dios acepta su arrepentimiento o los castiga, pues ellos han cometido muchas injusticias.","translation_en":"Not for you, [O Muhammad, but for Allah], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers.","theme":"hope"},{"surahNumber":5,"ayahNumber":99,"surahName":"Al-Maaida","arabic":"مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ","translation_ar":"ما على ٱلرسول إلا ٱلبلغ  وٱلله يعلم ما تبدون وما تكتمون","translation_es":"El Mensajero solo tiene la obligación de transmitir el Mensaje, Dios es Quien sabe lo que manifiestan y lo que ocultan.","translation_en":"Not upon the Messenger is [responsibility] except [for] notification. And Allah knows whatever you reveal and whatever you conceal.","theme":"knowledge"},{"surahNumber":11,"ayahNumber":9,"surahName":"Hud","arabic":"وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةًۭ ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌۭ كَفُورٌۭ","translation_ar":"ولئن أذقنا ٱلإنسن منا رحمة ثم نزعنها منه إنه لئوس كفور","translation_es":"Si le concedo a la persona algo de Mi gracia y luego se la quito, se desespera y se muestra desagradecida.","translation_en":"And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful.","theme":"mercy"},{"surahNumber":21,"ayahNumber":4,"surahName":"Al-Anbiyaa","arabic":"قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","translation_ar":"قال ربى يعلم ٱلقول فى ٱلسمآء وٱلأرض  وهو ٱلسميع ٱلعليم","translation_es":"Diles [¡oh, Mujámmad!]: “Mi Señor bien sabe todo lo que se dice en el cielo y en la Tierra. Él todo lo oye, todo lo sabe”.","translation_en":"The Prophet said, \"My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing.\"","theme":"knowledge"},{"surahNumber":22,"ayahNumber":8,"surahName":"Al-Hajj","arabic":"وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَلَا هُدًۭى وَلَا كِتَٰبٍۢ مُّنِيرٍۢ","translation_ar":"ومن ٱلناس من يجدل فى ٱلله بغير علم ولا هدى ولا كتب منير","translation_es":"Hay gente que discute acerca de Dios sin conocimiento, sin guía ni Libro que los ilumine.","translation_en":"And of the people is he who disputes about Allah without knowledge or guidance or an enlightening book [from Him],","theme":"light"},{"surahNumber":29,"ayahNumber":69,"surahName":"Al-Ankaboot","arabic":"وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ","translation_ar":"وٱلذين جهدوا فينا لنهدينهم سبلنا  وإن ٱلله لمع ٱلمحسنين","translation_es":"A quienes se esfuercen por Mi causa los guiaré por Mis caminos. Dios está con los que hacen el bien.","translation_en":"And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good.","theme":"mercy"},{"surahNumber":38,"ayahNumber":43,"surahName":"Saad","arabic":"وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ","translation_ar":"ووهبنا لهٓ أهله ومثلهم معهم رحمة منا وذكرى لأولى ٱلألبب","translation_es":"Lo agracié con hijos [como los que tenía] y tantos más, como una misericordia mía, para que sea un recuerdo y motivo de reflexión para los dotados de intelecto.","translation_en":"And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.","theme":"mercy"},{"surahNumber":39,"ayahNumber":27,"surahName":"Az-Zumar","arabic":"وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ لَّعَلَّهُمْ يَتَذَكَّرُونَ","translation_ar":"ولقد ضربنا للناس فى هذا ٱلقرءان من كل مثل لعلهم يتذكرون","translation_es":"He expuesto en el Corán toda clase de ejemplos para que reflexionen.","translation_en":"And We have certainly presented for the people in this Qur'an from every [kind of] example - that they might remember.","theme":"knowledge"},{"surahNumber":10,"ayahNumber":25,"surahName":"Yunus","arabic":"وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"وٱلله يدعوٓا إلى دار ٱلسلم ويهدى من يشآء إلى صرط مستقيم","translation_es":"Dios convoca a la morada de la paz y guía a quien quiere por el sendero recto.","translation_en":"And Allah invites to the Home of Peace and guides whom He wills to a straight path","theme":"light"},{"surahNumber":10,"ayahNumber":43,"surahName":"Yunus","arabic":"وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ","translation_ar":"ومنهم من ينظر إليك  أفأنت تهدى ٱلعمى ولو كانوا لا يبصرون","translation_es":"Algunos de ellos te miran, pero, ¿acaso tú puedes hacer ver a quien Dios ha enceguecido?","translation_en":"And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?","theme":"light"},{"surahNumber":16,"ayahNumber":9,"surahName":"An-Nahl","arabic":"وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌۭ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ","translation_ar":"وعلى ٱلله قصد ٱلسبيل ومنها جآئر  ولو شآء لهدىكم أجمعين","translation_es":"Dios es Quien enseña cuál es el sendero recto, del que muchos se desvían. Si hubiera querido los habría guiado a todos.","translation_en":"And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.","theme":"light"},{"surahNumber":34,"ayahNumber":26,"surahName":"Saba","arabic":"قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ","translation_ar":"قل يجمع بيننا ربنا ثم يفتح بيننا بٱلحق وهو ٱلفتاح ٱلعليم","translation_es":"Diles: “Nuestro Señor nos congregará [el Día del Juicio], luego juzgará entre nosotros con equidad; Él es el verdadero Juez, y Él todo lo sabe”.","translation_en":"Say, \"Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge.\"","theme":"victory"},{"surahNumber":47,"ayahNumber":7,"surahName":"Muhammad","arabic":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ","translation_ar":"يٓأيها ٱلذين ءامنوٓا إن تنصروا ٱلله ينصركم ويثبت أقدامكم","translation_es":"¡Oh, creyentes! Si auxilian a Dios, Él los auxiliará y afirmará sus pasos.","translation_en":"O you who have believed, if you support Allah, He will support you and plant firmly your feet.","theme":"victory"},{"surahNumber":2,"ayahNumber":263,"surahName":"Al-Baqara","arabic":"۞ قَوْلٌۭ مَّعْرُوفٌۭ وَمَغْفِرَةٌ خَيْرٌۭ مِّن صَدَقَةٍۢ يَتْبَعُهَآ أَذًۭى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌۭ","translation_ar":" قول معروف ومغفرة خير من صدقة يتبعهآ أذى  وٱلله غنى حليم","translation_es":"Una palabra amable y perdonar es mejor que una caridad seguida de un agravio. Dios es Opulento, Indulgente.","translation_en":"Kind speech and forgiveness are better than charity followed by injury. And Allah is Free of need and Forbearing.","theme":"mercy"},{"surahNumber":7,"ayahNumber":113,"surahName":"Al-A'raaf","arabic":"وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ","translation_ar":"وجآء ٱلسحرة فرعون قالوٓا إن لنا لأجرا إن كنا نحن ٱلغلبين","translation_es":"Los hechiceros se presentaron ante el Faraón y dijeron: “Exigimos una recompensa si somos los vencedores”.","translation_en":"And the magicians came to Pharaoh. They said, \"Indeed for us is a reward if we are the predominant.\"","theme":"deeds"},{"surahNumber":7,"ayahNumber":197,"surahName":"Al-A'raaf","arabic":"وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ","translation_ar":"وٱلذين تدعون من دونه لا يستطيعون نصركم ولآ أنفسهم ينصرون","translation_es":"Los que ustedes invocan en vez de Dios no pueden auxiliarlos ni auxiliarse a ellos mismos.","translation_en":"And those you call upon besides Him are unable to help you, nor can they help themselves.\"","theme":"victory"},{"surahNumber":9,"ayahNumber":78,"surahName":"At-Tawba","arabic":"أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ","translation_ar":"ألم يعلموٓا أن ٱلله يعلم سرهم ونجوىهم وأن ٱلله علم ٱلغيوب","translation_es":"¿Acaso no saben que Dios conoce sus intenciones y sus conspiraciones? Dios conoce bien lo oculto.","translation_en":"Did they not know that Allah knows their secrets and their private conversations and that Allah is the Knower of the unseen?","theme":"knowledge"},{"surahNumber":12,"ayahNumber":92,"surahName":"Yusuf","arabic":"قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ","translation_ar":"قال لا تثريب عليكم ٱليوم  يغفر ٱلله لكم  وهو أرحم ٱلرحمين","translation_es":"Dijo [José]: “Hoy no les reprocharé nada de lo que hayan hecho en el pasado. Que Dios los perdone, Él es el más Misericordioso de los misericordiosos.","translation_en":"He said, \"No blame will there be upon you today. Allah will forgive you; and He is the most merciful of the merciful.\"","theme":"hope"},{"surahNumber":27,"ayahNumber":52,"surahName":"An-Naml","arabic":"فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَعْلَمُونَ","translation_ar":"فتلك بيوتهم خاوية بما ظلموٓا  إن فى ذلك لءاية لقوم يعلمون","translation_es":"Sus casas yacen vacías, porque cometieron injusticias. En ello hay un signo para quienes reflexionan.","translation_en":"So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know.","theme":"knowledge"},{"surahNumber":28,"ayahNumber":22,"surahName":"Al-Qasas","arabic":"وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ","translation_ar":"ولما توجه تلقآء مدين قال عسى ربىٓ أن يهدينى سوآء ٱلسبيل","translation_es":"Y cuando se encontraba camino a Madián dijo: “¡Pueda que mi Señor me guie por el camino correcto!”","translation_en":"And when he directed himself toward Madyan, he said, \"Perhaps my Lord will guide me to the sound way.\"","theme":"light"},{"surahNumber":35,"ayahNumber":34,"surahName":"Faatir","arabic":"وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ ۖ إِنَّ رَبَّنَا لَغَفُورٌۭ شَكُورٌ","translation_ar":"وقالوا ٱلحمد لله ٱلذىٓ أذهب عنا ٱلحزن  إن ربنا لغفور شكور","translation_es":"Y dirán: “¡Alabado sea Dios, que ha hecho desaparecer toda causa de tristeza! Nuestro Señor es Absolvedor, Recompensador.","translation_en":"And they will say, \"Praise to Allah, who has removed from us [all] sorrow. Indeed, our Lord is Forgiving and Appreciative -","theme":"hope"},{"surahNumber":37,"ayahNumber":158,"surahName":"As-Saaffaat","arabic":"وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًۭا ۚ وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ","translation_ar":"وجعلوا بينه وبين ٱلجنة نسبا  ولقد علمت ٱلجنة إنهم لمحضرون","translation_es":"También inventaron un parentesco entre Dios y los yinnes, pero los yinnes saben bien que comparecerán [ante Dios] para ser juzgados.","translation_en":"And they have claimed between Him and the jinn a lineage, but the jinn have already known that they [who made such claims] will be brought to [punishment].","theme":"paradise"},{"surahNumber":59,"ayahNumber":20,"surahName":"Al-Hashr","arabic":"لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ ۚ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ","translation_ar":"لا يستوىٓ أصحب ٱلنار وأصحب ٱلجنة  أصحب ٱلجنة هم ٱلفآئزون","translation_es":"No se equiparan los compañeros del Infierno con los compañeros del Paraíso. Los compañeros del Paraíso son los que triunfan.","translation_en":"Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success].","theme":"paradise"},{"surahNumber":74,"ayahNumber":56,"surahName":"Al-Muddaththir","arabic":"وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ","translation_ar":"وما يذكرون إلآ أن يشآء ٱلله  هو أهل ٱلتقوى وأهل ٱلمغفرة","translation_es":"Pero solo lo harán aquellos para quienes Dios quiera la guía. Solo Él es digno de ser adorado, y solo Él es la fuente del perdón.","translation_en":"And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness.","theme":"light"},{"surahNumber":3,"ayahNumber":171,"surahName":"Aal-i-Imraan","arabic":"۞ يَسْتَبْشِرُونَ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ","translation_ar":" يستبشرون بنعمة من ٱلله وفضل وأن ٱلله لا يضيع أجر ٱلمؤمنين","translation_es":"Se congratulan unos a otros por la gracia y el favor de Dios. Porque Dios recompensa a los creyentes.","translation_en":"They receive good tidings of favor from Allah and bounty and [of the fact] that Allah does not allow the reward of believers to be lost -","theme":"deeds"},{"surahNumber":8,"ayahNumber":4,"surahName":"Al-Anfaal","arabic":"أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّۭا ۚ لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ","translation_ar":"أولٓئك هم ٱلمؤمنون حقا  لهم درجت عند ربهم ومغفرة ورزق كريم","translation_es":"Estos son los verdaderos creyentes, que alcanzarán grados elevados ante su Señor, el perdón y un sustento generoso.","translation_en":"Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.","theme":"mercy"},{"surahNumber":9,"ayahNumber":15,"surahName":"At-Tawba","arabic":"وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","translation_ar":"ويذهب غيظ قلوبهم  ويتوب ٱلله على من يشآء  وٱلله عليم حكيم","translation_es":"removiendo la ira que hay en ellos. Dios acepta el arrepentimiento de quien quiere. Dios lo sabe todo, es Sabio.","translation_en":"And remove the fury in the believers' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.","theme":"hope"},{"surahNumber":17,"ayahNumber":96,"surahName":"Al-Israa","arabic":"قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا","translation_ar":"قل كفى بٱلله شهيدا بينى وبينكم  إنه كان بعباده خبيرا بصيرا","translation_es":"Diles: “Dios es suficiente testigo de mi veracidad entre ustedes y yo. Él está bien informado sobre Sus siervos y los observa”.","translation_en":"Say, \"Sufficient is Allah as Witness between me and you. Indeed he is ever, concerning His servants, Acquainted and Seeing.\"","theme":"ease"},{"surahNumber":68,"ayahNumber":17,"surahName":"Al-Qalam","arabic":"إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ","translation_ar":"إنا بلونهم كما بلونآ أصحب ٱلجنة إذ أقسموا ليصرمنها مصبحين","translation_es":"[A los que te desmienten] los he puesto a prueba [con la prosperidad], como probé a los dueños del huerto, cuando juraron recoger sus frutos por la mañana","translation_en":"Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning","theme":"paradise"},{"surahNumber":12,"ayahNumber":52,"surahName":"Yusuf","arabic":"ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ","translation_ar":"ذلك ليعلم أنى لم أخنه بٱلغيب وأن ٱلله لا يهدى كيد ٱلخآئنين","translation_es":"Digo esto para que [mi esposo] sepa que no lo traicioné en su ausencia, y sé bien que Dios desbarata las intrigas de los traidores.","translation_en":"That is so al-'Azeez will know that I did not betray him in [his] absence and that Allah does not guide the plan of betrayers.","theme":"knowledge"},{"surahNumber":16,"ayahNumber":37,"surahName":"An-Nahl","arabic":"إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ ۖ وَمَا لَهُم مِّن نَّٰصِرِينَ","translation_ar":"إن تحرص على هدىهم فإن ٱلله لا يهدى من يضل  وما لهم من نصرين","translation_es":"Debes saber [¡oh, Mujámmad!] que por más que te empeñes en guiarlos, Dios no guiará [por la fuerza] a quienes hayan elegido el extravío. Éstos no tendrán quién los auxilie.","translation_en":"[Even] if you should strive for their guidance, [O Muhammad], indeed, Allah does not guide those He sends astray, and they will have no helpers.","theme":"light"},{"surahNumber":18,"ayahNumber":13,"surahName":"Al-Kahf","arabic":"نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًۭى","translation_ar":"نحن نقص عليك نبأهم بٱلحق  إنهم فتية ءامنوا بربهم وزدنهم هدى","translation_es":"Te relato su verdadera historia: Eran jóvenes que creían en su Señor y les aumenté su guía,","translation_en":"It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.","theme":"light"},{"surahNumber":24,"ayahNumber":25,"surahName":"An-Noor","arabic":"يَوْمَئِذٍۢ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ","translation_ar":"يومئذ يوفيهم ٱلله دينهم ٱلحق ويعلمون أن ٱلله هو ٱلحق ٱلمبين","translation_es":"Ese día, Dios les pagará lo que merecen por lo que hicieron, y finalmente sabrán que Dios es la Verdad evidente.","translation_en":"That Day, Allah will pay them in full their deserved recompense, and they will know that it is Allah who is the perfect in justice.","theme":"knowledge"},{"surahNumber":67,"ayahNumber":22,"surahName":"Al-Mulk","arabic":"أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"أفمن يمشى مكبا على وجههٓ أهدىٓ أمن يمشى سويا على صرط مستقيم","translation_es":"¿Quién está mejor encaminado: el que camina cabizbajo y tropezando o el que camina erguido por el sendero recto?","translation_en":"Then is one who walks fallen on his face better guided or one who walks erect on a straight path?","theme":"light"},{"surahNumber":2,"ayahNumber":82,"surahName":"Al-Baqara","arabic":"وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ","translation_ar":"وٱلذين ءامنوا وعملوا ٱلصلحت أولٓئك أصحب ٱلجنة  هم فيها خلدون","translation_es":"Pero en cambio, quienes hayan creído y obrado rectamente serán los moradores del Paraíso donde vivirán eternamente.","translation_en":"But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally.","theme":"paradise"},{"surahNumber":7,"ayahNumber":170,"surahName":"Al-A'raaf","arabic":"وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ","translation_ar":"وٱلذين يمسكون بٱلكتب وأقاموا ٱلصلوة إنا لا نضيع أجر ٱلمصلحين","translation_es":"Aquellos que se aferran al Libro y realizan la oración prescrita sepan que jamás dejaré de recompensar a los que hacen el bien.","translation_en":"But those who hold fast to the Book and establish prayer - indeed, We will not allow to be lost the reward of the reformers.","theme":"deeds"},{"surahNumber":25,"ayahNumber":31,"surahName":"Al-Furqaan","arabic":"وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا مِّنَ ٱلْمُجْرِمِينَ ۗ وَكَفَىٰ بِرَبِّكَ هَادِيًۭا وَنَصِيرًۭا","translation_ar":"وكذلك جعلنا لكل نبى عدوا من ٱلمجرمين  وكفى بربك هاديا ونصيرا","translation_es":"[Sabe, ¡oh, Mujámmad!, que] dispuse que todos los Profetas tuvieran enemigos de entre los pecadores. Pero tu Señor es suficiente como guía y protector.","translation_en":"And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.","theme":"ease"},{"surahNumber":28,"ayahNumber":16,"surahName":"Al-Qasas","arabic":"قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","translation_ar":"قال رب إنى ظلمت نفسى فٱغفر لى فغفر لهٓ  إنه هو ٱلغفور ٱلرحيم","translation_es":"Dijo: “¡Señor mío! He sido injusto conmigo mismo; perdóname”. Y [Dios] lo perdonó, porque Él es Absolvedor, Misericordioso.","translation_en":"He said, \"My Lord, indeed I have wronged myself, so forgive me,\" and He forgave him. Indeed, He is the Forgiving, the Merciful.","theme":"hope"},{"surahNumber":28,"ayahNumber":49,"surahName":"Al-Qasas","arabic":"قُلْ فَأْتُوا۟ بِكِتَٰبٍۢ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ","translation_ar":"قل فأتوا بكتب من عند ٱلله هو أهدى منهمآ أتبعه إن كنتم صدقين","translation_es":"Diles [¡oh, Mujámmad!]: “Traigan un libro proveniente de Dios que sea una guía mejor que estos dos y yo lo seguiré, si es que dicen la verdad.","translation_en":"Say, \"Then bring a scripture from Allah which is more guiding than either of them that I may follow it, if you should be truthful.\"","theme":"light"},{"surahNumber":34,"ayahNumber":4,"surahName":"Saba","arabic":"لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۚ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ","translation_ar":"ليجزى ٱلذين ءامنوا وعملوا ٱلصلحت  أولٓئك لهم مغفرة ورزق كريم","translation_es":"[La Resurrección es] para recompensar a los creyentes que obraron correctamente; ellos obtendrán el perdón y un sustento generoso.","translation_en":"That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.","theme":"mercy"},{"surahNumber":49,"ayahNumber":5,"surahName":"Al-Hujuraat","arabic":"وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًۭا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم  وٱلله غفور رحيم","translation_es":"Mejor sería que esperaran pacientemente hasta que tú salgas; pero [sepan que] Dios es Absolvedor, Misericordioso.","translation_en":"And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":2,"ayahNumber":199,"surahName":"Al-Baqara","arabic":"ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ","translation_ar":"ثم أفيضوا من حيث أفاض ٱلناس وٱستغفروا ٱلله  إن ٱلله غفور رحيم","translation_es":"Luego avancen en multitudes por donde lo hace la gente e imploren el perdón de Dios. Dios es Absolvedor, Misericordioso.","translation_en":"Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":4,"ayahNumber":174,"surahName":"An-Nisaa","arabic":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌۭ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًۭا مُّبِينًۭا","translation_ar":"يٓأيها ٱلناس قد جآءكم برهن من ربكم وأنزلنآ إليكم نورا مبينا","translation_es":"¡Oh, seres humanos! Les ha llegado una prueba de su Señor [el Profeta], y les he hecho descender una luz que ilumina [el Corán].","translation_en":"O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light.","theme":"light"},{"surahNumber":11,"ayahNumber":41,"surahName":"Hud","arabic":"۞ وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ ۚ إِنَّ رَبِّى لَغَفُورٌۭ رَّحِيمٌۭ","translation_ar":" وقال ٱركبوا فيها بسم ٱلله مجرىها ومرسىهآ  إن ربى لغفور رحيم","translation_es":"Dijo [Noé]: “¡Suban al arca! ¡Que en el nombre de Dios navegue y llegue a buen puerto! Mi Señor es Perdonador, Misericordioso”.","translation_en":"And [Noah] said, \"Embark therein; in the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful.\"","theme":"hope"},{"surahNumber":23,"ayahNumber":62,"surahName":"Al-Muminoon","arabic":"وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَلَدَيْنَا كِتَٰبٌۭ يَنطِقُ بِٱلْحَقِّ ۚ وَهُمْ لَا يُظْلَمُونَ","translation_ar":"ولا نكلف نفسا إلا وسعها  ولدينا كتب ينطق بٱلحق  وهم لا يظلمون","translation_es":"No exijo a nadie por encima de sus posibilidades. [Sepan que] tengo un Libro que dice la verdad, y nadie será tratado injustamente.","translation_en":"And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.","theme":"ease"},{"surahNumber":25,"ayahNumber":6,"surahName":"Al-Furqaan","arabic":"قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًۭا رَّحِيمًۭا","translation_ar":"قل أنزله ٱلذى يعلم ٱلسر فى ٱلسموت وٱلأرض  إنه كان غفورا رحيما","translation_es":"Diles [¡oh, Mujámmad!]: “Lo ha revelado Quien conoce lo oculto en los cielos y en la Tierra; Él es Absolvedor, Misericordioso”.","translation_en":"Say, [O Muhammad], \"It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful.\"","theme":"hope"},{"surahNumber":64,"ayahNumber":17,"surahName":"At-Taghaabun","arabic":"إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ","translation_ar":"إن تقرضوا ٱلله قرضا حسنا يضعفه لكم ويغفر لكم  وٱلله شكور حليم","translation_es":"Si hacen a Dios un préstamo generoso, Él lo devolverá multiplicado y perdonará sus faltas. Dios es Agradecido, Tolerante,","translation_en":"If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.","theme":"hope"},{"surahNumber":3,"ayahNumber":148,"surahName":"Aal-i-Imraan","arabic":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","translation_ar":"فٔاتىهم ٱلله ثواب ٱلدنيا وحسن ثواب ٱلءاخرة  وٱلله يحب ٱلمحسنين","translation_es":"Dios les premió en esta vida y les favorecerá con una recompensa mayor en la otra, porque Dios ama a los que hacen el bien.","translation_en":"So Allah gave them the reward of this world and the good reward of the Hereafter. And Allah loves the doers of good.","theme":"mercy"},{"surahNumber":6,"ayahNumber":3,"surahName":"Al-An'aam","arabic":"وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ","translation_ar":"وهو ٱلله فى ٱلسموت وفى ٱلأرض  يعلم سركم وجهركم ويعلم ما تكسبون","translation_es":"Él es Al-lah, el adorado en los cielos y en la Tierra. Sabe lo que esconden y lo que manifiestan, y sabe lo que obtienen [con sus obras].","translation_en":"And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.","theme":"knowledge"},{"surahNumber":6,"ayahNumber":87,"surahName":"Al-An'aam","arabic":"وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translation_ar":"ومن ءابآئهم وذريتهم وإخونهم  وٱجتبينهم وهدينهم إلى صرط مستقيم","translation_es":"También distinguí a algunos de sus antepasados, descendientes y hermanos. Los elegí y los guie por el sendero recto.","translation_en":"And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.","theme":"light"},{"surahNumber":6,"ayahNumber":147,"surahName":"Al-An'aam","arabic":"فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍۢ وَٰسِعَةٍۢ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ","translation_ar":"فإن كذبوك فقل ربكم ذو رحمة وسعة ولا يرد بأسه عن ٱلقوم ٱلمجرمين","translation_es":"Y si te desmienten diles: “Su Señor es inmensamente Misericordioso, pero Su castigo caerá con toda certeza sobre los que se hunden en el pecado”.","translation_en":"So if they deny you, [O Muhammad], say, \"Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals.\"","theme":"mercy"},{"surahNumber":10,"ayahNumber":89,"surahName":"Yunus","arabic":"قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ","translation_ar":"قال قد أجيبت دعوتكما فٱستقيما ولا تتبعآن سبيل ٱلذين لا يعلمون","translation_es":"Dijo [Dios]: “El ruego que han hecho fue respondido. Sean rectos y no sigan el camino de los ignorantes”.","translation_en":"[Allah] said, \"Your supplication has been answered.\" So remain on a right course and follow not the way of those who do not know.\"","theme":"knowledge"},{"surahNumber":16,"ayahNumber":23,"surahName":"An-Nahl","arabic":"لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ","translation_ar":"لا جرم أن ٱلله يعلم ما يسرون وما يعلنون  إنه لا يحب ٱلمستكبرين","translation_es":"No hay duda de que Dios sabe lo que ocultan y lo que manifiestan. Él no ama a los soberbios.","translation_en":"Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.","theme":"knowledge"},{"surahNumber":17,"ayahNumber":24,"surahName":"Al-Israa","arabic":"وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا","translation_ar":"وٱخفض لهما جناح ٱلذل من ٱلرحمة وقل رب ٱرحمهما كما ربيانى صغيرا","translation_es":"Trátenlos con humildad y compasión, y rueguen [por ellos diciendo]: “¡Oh, Señor mío! Ten misericordia de ellos como ellos la tuvieron conmigo cuando me criaron siendo niño”.","translation_en":"And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small.\"","theme":"mercy"},{"surahNumber":17,"ayahNumber":28,"surahName":"Al-Israa","arabic":"وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍۢ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًۭا مَّيْسُورًۭا","translation_ar":"وإما تعرضن عنهم ٱبتغآء رحمة من ربك ترجوها فقل لهم قولا ميسورا","translation_es":"Pero si no puedes darles una ayuda, y esperas una misericordia de tu Señor, excúsate con amabilidad.","translation_en":"And if you [must] turn away from the needy awaiting mercy from your Lord which you expect, then speak to them a gentle word.","theme":"mercy"},{"surahNumber":18,"ayahNumber":65,"surahName":"Al-Kahf","arabic":"فَوَجَدَا عَبْدًۭا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةًۭ مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًۭا","translation_ar":"فوجدا عبدا من عبادنآ ءاتينه رحمة من عندنا وعلمنه من لدنا علما","translation_es":"Encontraron a uno de Mis siervos [Al Jidr] a quien había agraciado con Mi misericordia y enseñado ciertos conocimientos [que Moisés no poseía].","translation_en":"And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.","theme":"mercy"},{"surahNumber":20,"ayahNumber":117,"surahName":"Taa-Haa","arabic":"فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّۭ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ","translation_ar":"فقلنا يٓٔادم إن هذا عدو لك ولزوجك فلا يخرجنكما من ٱلجنة فتشقىٓ","translation_es":"Dije: “¡Oh, Adán! Este [el demonio] es un enemigo para ti y para tu esposa; que no los haga expulsar del Paraíso pues serás un desdichado.","translation_en":"So We said, \"O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer.","theme":"paradise"},{"surahNumber":26,"ayahNumber":41,"surahName":"Ash-Shu'araa","arabic":"فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ","translation_ar":"فلما جآء ٱلسحرة قالوا لفرعون أئن لنا لأجرا إن كنا نحن ٱلغلبين","translation_es":"Cuando los hechiceros se presentaron ante el Faraón, consultaron: “¿Tendremos una recompensa si somos los vencedores?”","translation_en":"And when the magicians arrived, they said to Pharaoh, \"Is there indeed for us a reward if we are the predominant?\"","theme":"deeds"},{"surahNumber":32,"ayahNumber":24,"surahName":"As-Sajda","arabic":"وَجَعَلْنَا مِنْهُمْ أَئِمَّةًۭ يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ ۖ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ","translation_ar":"وجعلنا منهم أئمة يهدون بأمرنا لما صبروا  وكانوا بٔايتنا يوقنون","translation_es":"Hice de algunos de ellos líderes ejemplares para guiar [a la gente] por Mi voluntad, siempre que sean pacientes y tengan certeza de Mis signos.","translation_en":"And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs.","theme":"sadness"},{"surahNumber":40,"ayahNumber":57,"surahName":"Ghafir","arabic":"لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","translation_ar":"لخلق ٱلسموت وٱلأرض أكبر من خلق ٱلناس ولكن أكثر ٱلناس لا يعلمون","translation_es":"La creación de los cielos y de la Tierra es más grandiosa que la creación de los seres humanos, pero la mayoría de ellos lo ignoran.","translation_en":"The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know.","theme":"knowledge"},{"surahNumber":61,"ayahNumber":8,"surahName":"As-Saff","arabic":"يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ","translation_ar":"يريدون ليطفٔوا نور ٱلله بأفوههم وٱلله متم نوره ولو كره ٱلكفرون","translation_es":"Pretenden extinguir la luz [del Mensaje] de Dios con las mentiras que pronuncian sus bocas, pero Dios hará que Su luz resplandezca, aunque esto desagrade a los que rechazan el Mensaje.","translation_en":"They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.","theme":"light"},{"surahNumber":67,"ayahNumber":29,"surahName":"Al-Mulk","arabic":"قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ","translation_ar":"قل هو ٱلرحمن ءامنا به وعليه توكلنا  فستعلمون من هو فى ضلل مبين","translation_es":"Diles: “Él es el Misericordioso, creemos en Él y en Él depositamos nuestra confianza. Ya verán [el Día del juicio] quién es el que está en un error evidente”.","translation_en":"Say, \"He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error.\"","theme":"victory"},{"surahNumber":72,"ayahNumber":28,"surahName":"Al-Jinn","arabic":"لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا","translation_ar":"ليعلم أن قد أبلغوا رسلت ربهم وأحاط بما لديهم وأحصى كل شىء عددا","translation_es":"para cerciorarse que ha transmitido los Mensajes de su Señor. Él tiene completo conocimiento de todo cuanto les sucede y lleva la cuenta exacta de todo”.","translation_en":"That he may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number.","theme":"knowledge"},{"surahNumber":4,"ayahNumber":110,"surahName":"An-Nisaa","arabic":"وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًۭا رَّحِيمًۭا","translation_ar":"ومن يعمل سوٓءا أو يظلم نفسه ثم يستغفر ٱلله يجد ٱلله غفورا رحيما","translation_es":"Quien obre mal o sea injusto consigo mismo, pero pida perdón a Dios, encontrará que Dios es Perdonador, Misericordioso.","translation_en":"And whoever does a wrong or wrongs himself but then seeks forgiveness of Allah will find Allah Forgiving and Merciful.","theme":"hope"},{"surahNumber":4,"ayahNumber":149,"surahName":"An-Nisaa","arabic":"إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍۢ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّۭا قَدِيرًا","translation_ar":"إن تبدوا خيرا أو تخفوه أو تعفوا عن سوٓء فإن ٱلله كان عفوا قديرا","translation_es":"Si hacen públicas sus buenas obras o si las esconden, o si perdonan una ofensa, sepan que Dios es Perdonador, Poderoso.","translation_en":"If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allah is ever Pardoning and Competent.","theme":"mercy"},{"surahNumber":5,"ayahNumber":39,"surahName":"Al-Maaida","arabic":"فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ","translation_ar":"فمن تاب من بعد ظلمه وأصلح فإن ٱلله يتوب عليه  إن ٱلله غفور رحيم","translation_es":"Pero a quien se arrepienta luego de cometer un delito o injusticia y enmiende, Dios lo perdonará, porque Dios es Perdonador, Misericordioso.","translation_en":"But whoever repents after his wrongdoing and reforms, indeed, Allah will turn to him in forgiveness. Indeed, Allah is Forgiving and Merciful.","theme":"hope"},{"surahNumber":8,"ayahNumber":61,"surahName":"Al-Anfaal","arabic":"۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","translation_ar":" وإن جنحوا للسلم فٱجنح لها وتوكل على ٱلله  إنه هو ٱلسميع ٱلعليم","translation_es":"Si [los incrédulos] se inclinan por la paz, acéptala tú también y encomiéndate a Dios. Él todo lo oye, todo lo sabe.","translation_en":"And if they incline to peace, then incline to it [also] and rely upon Allah. Indeed, it is He who is the Hearing, the Knowing.","theme":"victory"},{"surahNumber":16,"ayahNumber":39,"surahName":"An-Nahl","arabic":"لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ","translation_ar":"ليبين لهم ٱلذى يختلفون فيه وليعلم ٱلذين كفروٓا أنهم كانوا كذبين","translation_es":"[Dios los resucitará] para demostrarles cuál era la Verdad sobre la que discrepaban y para que los incrédulos comprendan que estaban equivocados.","translation_en":"[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars.","theme":"knowledge"},{"surahNumber":17,"ayahNumber":25,"surahName":"Al-Israa","arabic":"رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ ۚ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًۭا","translation_ar":"ربكم أعلم بما فى نفوسكم  إن تكونوا صلحين فإنه كان للأوبين غفورا","translation_es":"Su Señor es Quien mejor conoce lo que hay en sus corazones. Si son piadosos, sepan que Él perdona a los que se arrepienten.","translation_en":"Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving.","theme":"hope"},{"surahNumber":42,"ayahNumber":17,"surahName":"Ash-Shura","arabic":"ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ ۗ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌۭ","translation_ar":"ٱلله ٱلذىٓ أنزل ٱلكتب بٱلحق وٱلميزان  وما يدريك لعل ٱلساعة قريب","translation_es":"Dios es Quien reveló el Libro con la verdad y la justicia. ¿Y quién sabe? Quizá la Hora esté cercana.","translation_en":"It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.","theme":"hope"},{"surahNumber":42,"ayahNumber":25,"surahName":"Ash-Shura","arabic":"وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ","translation_ar":"وهو ٱلذى يقبل ٱلتوبة عن عباده ويعفوا عن ٱلسئات ويعلم ما تفعلون","translation_es":"Él es Quien acepta el arrepentimiento de Sus siervos, perdona sus pecados y está bien enterado de cuanto hacen.","translation_en":"And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.","theme":"mercy"},{"surahNumber":43,"ayahNumber":86,"surahName":"Az-Zukhruf","arabic":"وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ","translation_ar":"ولا يملك ٱلذين يدعون من دونه ٱلشفعة إلا من شهد بٱلحق وهم يعلمون","translation_es":"Aquellos que son invocados en lugar de Dios no poseen la facultad de interceder por nadie. Solo pueden interceder quienes atestiguan la Verdad y tienen conocimiento.","translation_en":"And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know.","theme":"knowledge"},{"surahNumber":64,"ayahNumber":8,"surahName":"At-Taghaabun","arabic":"فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ","translation_ar":"فٔامنوا بٱلله ورسوله وٱلنور ٱلذىٓ أنزلنا  وٱلله بما تعملون خبير","translation_es":"Crean en Dios, en Su Mensajero y en la Luz que ha revelado [el Corán]. Dios está bien informado de cuanto hacen.","translation_en":"So believe in Allah and His Messenger and the Qur'an which We have sent down. And Allah is Acquainted with what you do.","theme":"light"},{"surahNumber":7,"ayahNumber":198,"surahName":"Al-A'raaf","arabic":"وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ","translation_ar":"وإن تدعوهم إلى ٱلهدى لا يسمعوا  وترىهم ينظرون إليك وهم لا يبصرون","translation_es":"Cuando ustedes los invocan pidiendo guía, no los oyen. Pareciera que los miran, pero en realidad no los ven.","translation_en":"And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see.","theme":"light"},{"surahNumber":10,"ayahNumber":84,"surahName":"Yunus","arabic":"وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ","translation_ar":"وقال موسى يقوم إن كنتم ءامنتم بٱلله فعليه توكلوٓا إن كنتم مسلمين","translation_es":"Dijo Moisés: “¡Oh, pueblo mío! Si creen, encomiéndense a Dios, si es que realmente se han entregado a Él”.","translation_en":"And Moses said, \"O my people, if you have believed in Allah, then rely upon Him, if you should be Muslims.\"","theme":"victory"},{"surahNumber":13,"ayahNumber":28,"surahName":"Ar-Ra'd","arabic":"ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ","translation_ar":"ٱلذين ءامنوا وتطمئن قلوبهم بذكر ٱلله  ألا بذكر ٱلله تطمئن ٱلقلوب","translation_es":"Los corazones de los creyentes se sosiegan con el recuerdo de Dios. ¿Acaso no es con el recuerdo de Dios que se sosiegan los corazones?","translation_en":"Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured.\"","theme":"sadness"},{"surahNumber":17,"ayahNumber":86,"surahName":"Al-Israa","arabic":"وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا","translation_ar":"ولئن شئنا لنذهبن بٱلذىٓ أوحينآ إليك ثم لا تجد لك به علينا وكيلا","translation_es":"Si quisiera, borraría todo lo que te he revelado, y entonces no encontrarías quién abogara por ti ante Mí [para que lo pudieras recordar].","translation_en":"And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us.","theme":"victory"},{"surahNumber":18,"ayahNumber":88,"surahName":"Al-Kahf","arabic":"وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًۭا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ ۖ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًۭا","translation_ar":"وأما من ءامن وعمل صلحا فله جزآء ٱلحسنى  وسنقول له من أمرنا يسرا","translation_es":"Pero en cambio, a quien crea y obre correctamente se le concederá una bella recompensa, y le corresponderé con un trato amable”.","translation_en":"But as for one who believes and does righteousness, he will have a reward of Paradise, and we will speak to him from our command with ease.\"","theme":"ease"},{"surahNumber":25,"ayahNumber":15,"surahName":"Al-Furqaan","arabic":"قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۚ كَانَتْ لَهُمْ جَزَآءًۭ وَمَصِيرًۭا","translation_ar":"قل أذلك خير أم جنة ٱلخلد ٱلتى وعد ٱلمتقون  كانت لهم جزآء ومصيرا","translation_es":"Diles [¡oh, Mujámmad!]: “¿Acaso [ese tormento] es mejor que el Paraíso eterno que se les ha prometido a los piadosos? Para ellos [los piadosos] el Paraíso será su recompensa y destino final,","translation_en":"Say, \"Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.","theme":"paradise"},{"surahNumber":28,"ayahNumber":56,"surahName":"Al-Qasas","arabic":"إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۚ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ","translation_ar":"إنك لا تهدى من أحببت ولكن ٱلله يهدى من يشآء  وهو أعلم بٱلمهتدين","translation_es":"Tú no puedes guiar a quien amas, sino que Dios guía a quien Él quiere. Él sabe quiénes seguirán la guía.","translation_en":"Indeed, [O Muhammad], you do not guide whom you like, but Allah guides whom He wills. And He is most knowing of the [rightly] guided.","theme":"light"},{"surahNumber":63,"ayahNumber":2,"surahName":"Al-Munaafiqoon","arabic":"ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ","translation_ar":"ٱتخذوٓا أيمنهم جنة فصدوا عن سبيل ٱلله  إنهم سآء ما كانوا يعملون","translation_es":"[Los hipócritas] se escudan en sus juramentos para apartar [a algunas personas] del sendero de Dios. ¡Qué pésimo es lo que hacen!","translation_en":"They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.","theme":"paradise"},{"surahNumber":67,"ayahNumber":2,"surahName":"Al-Mulk","arabic":"ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ","translation_ar":"ٱلذى خلق ٱلموت وٱلحيوة ليبلوكم أيكم أحسن عملا  وهو ٱلعزيز ٱلغفور","translation_es":"Él es Quien creó la muerte y la vida para probarlos y distinguir quién obra mejor. Él es el Poderoso, el Perdonador.","translation_en":"[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -","theme":"hope"},{"surahNumber":3,"ayahNumber":133,"surahName":"Aal-i-Imraan","arabic":"۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ","translation_ar":" وسارعوٓا إلى مغفرة من ربكم وجنة عرضها ٱلسموت وٱلأرض أعدت للمتقين","translation_es":"Y apresúrense a buscar el perdón de su Señor y un Paraíso tan vasto como los cielos y la Tierra, que ha sido reservado para los que tienen consciencia de Dios [y cumplen la ley],","translation_en":"And hasten to forgiveness from your Lord and a garden as wide as the heavens and earth, prepared for the righteous","theme":"paradise"},{"surahNumber":16,"ayahNumber":127,"surahName":"An-Nahl","arabic":"وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍۢ مِّمَّا يَمْكُرُونَ","translation_ar":"وٱصبر وما صبرك إلا بٱلله  ولا تحزن عليهم ولا تك فى ضيق مما يمكرون","translation_es":"Sé paciente y sabe que la paciencia es una virtud que Dios concede a quien quiere. No sientas pena [por la incredulidad de tu pueblo] ni te angusties por lo que traman.","translation_en":"And be patient, [O Muhammad], and your patience is not but through Allah. And do not grieve over them and do not be in distress over what they conspire.","theme":"sadness"},{"surahNumber":32,"ayahNumber":16,"surahName":"As-Sajda","arabic":"تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًۭا وَطَمَعًۭا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ","translation_ar":"تتجافى جنوبهم عن ٱلمضاجع يدعون ربهم خوفا وطمعا ومما رزقنهم ينفقون","translation_es":"se levantan de sus lechos para invocar a su Señor con temor y anhelo [de Su respuesta], y dan en caridad parte de lo que les he proveído.","translation_en":"They arise from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend.","theme":"deeds"},{"surahNumber":38,"ayahNumber":6,"surahName":"Saad","arabic":"وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ ۖ إِنَّ هَٰذَا لَشَىْءٌۭ يُرَادُ","translation_ar":"وٱنطلق ٱلملأ منهم أن ٱمشوا وٱصبروا علىٓ ءالهتكم  إن هذا لشىء يراد","translation_es":"Los nobles y poderosos de entre ellos se marcharon diciendo: “Déjenlo, y sigan [adorando] a sus ídolos, pues él solo pretende obtener poder sobre nosotros.","translation_en":"And the eminent among them went forth, [saying], \"Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.","theme":"sadness"},{"surahNumber":2,"ayahNumber":16,"surahName":"Al-Baqara","arabic":"أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ","translation_ar":"أولٓئك ٱلذين ٱشتروا ٱلضللة بٱلهدى فما ربحت تجرتهم وما كانوا مهتدين","translation_es":"Ellos vendieron la guía, cambiándola por el desvío, y tal negocio no les resultó provechoso, no siendo de los bien guiados.","translation_en":"Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.","theme":"light"},{"surahNumber":5,"ayahNumber":58,"surahName":"Al-Maaida","arabic":"وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًۭا وَلَعِبًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْقِلُونَ","translation_ar":"وإذا ناديتم إلى ٱلصلوة ٱتخذوها هزوا ولعبا  ذلك بأنهم قوم لا يعقلون","translation_es":"Cuando ustedes convocan a la oración, ellos se burlan y la toman a broma, porque son gente que no razona.","translation_en":"And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason.","theme":"knowledge"},{"surahNumber":9,"ayahNumber":89,"surahName":"At-Tawba","arabic":"أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ","translation_ar":"أعد ٱلله لهم جنت تجرى من تحتها ٱلأنهر خلدين فيها  ذلك ٱلفوز ٱلعظيم","translation_es":"Dios tiene reservado para ellos jardines [en el Paraíso] por donde corren ríos, donde morarán por toda la eternidad. Ese es el triunfo grandioso.","translation_en":"Allah has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment.","theme":"paradise"},{"surahNumber":17,"ayahNumber":17,"surahName":"Al-Israa","arabic":"وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍۢ ۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا","translation_ar":"وكم أهلكنا من ٱلقرون من بعد نوح  وكفى بربك بذنوب عباده خبيرا بصيرا","translation_es":"Así es como he destruido a muchas generaciones luego de Noé. ¡Es suficiente con que Dios vea y sepa de los pecados que cometen Sus siervos!","translation_en":"And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Acquainted and Seeing.","theme":"ease"},{"surahNumber":21,"ayahNumber":109,"surahName":"Al-Anbiyaa","arabic":"فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍۢ ۖ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌۭ مَّا تُوعَدُونَ","translation_ar":"فإن تولوا فقل ءاذنتكم على سوآء  وإن أدرىٓ أقريب أم بعيد ما توعدون","translation_es":"Pero si rechazan [el Mensaje] diles: “Les advierto sobre un castigo que caerá sobre todos por igual, aunque no tengo conocimiento si lo que les advierto está cerca o lejos.","translation_en":"But if they turn away, then say, \"I have announced to [all of] you equally. And I know not whether near or far is that which you are promised.","theme":"hope"},{"surahNumber":36,"ayahNumber":11,"surahName":"Yaseen","arabic":"إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍۢ وَأَجْرٍۢ كَرِيمٍ","translation_ar":"إنما تنذر من ٱتبع ٱلذكر وخشى ٱلرحمن بٱلغيب  فبشره بمغفرة وأجر كريم","translation_es":"Solo se beneficia con tu amonestación quien sigue el Mensaje y teme al Compasivo en su intimidad. A ellos anúnciales que obtendrán el perdón y una recompensa generosa.","translation_en":"You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.","theme":"mercy"},{"surahNumber":36,"ayahNumber":36,"surahName":"Yaseen","arabic":"سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ","translation_ar":"سبحن ٱلذى خلق ٱلأزوج كلها مما تنبت ٱلأرض ومن أنفسهم ومما لا يعلمون","translation_es":"Glorificado sea Aquel que creó todas las especies en pares; las que brotan de la tierra, los seres humanos y otras [criaturas] que desconocen.","translation_en":"Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.","theme":"knowledge"},{"surahNumber":40,"ayahNumber":9,"surahName":"Ghafir","arabic":"وَقِهِمُ ٱلسَّيِّـَٔاتِ ۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍۢ فَقَدْ رَحِمْتَهُۥ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ","translation_ar":"وقهم ٱلسئات  ومن تق ٱلسئات يومئذ فقد رحمته  وذلك هو ٱلفوز ٱلعظيم","translation_es":"Presérvalos de cometer pecados. Tú te apiadarás, cuando llegue el Día del Juicio, de aquel que haya sido preservado de cometer pecados. Ese será el triunfo grandioso”.","translation_en":"And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment.\"","theme":"paradise"},{"surahNumber":43,"ayahNumber":35,"surahName":"Az-Zukhruf","arabic":"وَزُخْرُفًۭا ۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَٱلْءَاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ","translation_ar":"وزخرفا  وإن كل ذلك لما متع ٱلحيوة ٱلدنيا  وٱلءاخرة عند ربك للمتقين","translation_es":"Todo estaría adornado con oro. Sin embargo [no lo hago porque] todo eso es solo parte de los placeres transitorios de la vida mundanal, mientras que la otra vida junto a tu Señor [es superior y] está reservada para los piadosos.","translation_en":"And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous.","theme":"light"},{"surahNumber":57,"ayahNumber":18,"surahName":"Al-Hadid","arabic":"إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌۭ كَرِيمٌۭ","translation_ar":"إن ٱلمصدقين وٱلمصدقت وأقرضوا ٱلله قرضا حسنا يضعف لهم ولهم أجر كريم","translation_es":"A los [hombres] que dan caridad y a las [mujeres] que dan caridad, que aportaron con sus bienes a la causa de Dios, les será multiplicado y serán recompensados generosamente.","translation_en":"Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allah a goodly loan - it will be multiplied for them, and they will have a noble reward.","theme":"mercy"},{"surahNumber":9,"ayahNumber":106,"surahName":"At-Tawba","arabic":"وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ","translation_ar":"وءاخرون مرجون لأمر ٱلله إما يعذبهم وإما يتوب عليهم  وٱلله عليم حكيم","translation_es":"Otros esperan el designio de Dios, Quien los castigará [si no se arrepienten] o los perdonará [si lo hacen]. Dios lo sabe todo, es Sabio.","translation_en":"And [there are] others deferred until the command of Allah - whether He will punish them or whether He will forgive them. And Allah is Knowing and Wise.","theme":"hope"},{"surahNumber":10,"ayahNumber":100,"surahName":"Yunus","arabic":"وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ","translation_ar":"وما كان لنفس أن تؤمن إلا بإذن ٱلله  ويجعل ٱلرجس على ٱلذين لا يعقلون","translation_es":"Nadie podrá creer a menos que Dios se lo permita, y Él dejará en el extravío a quienes no usen su razonamiento.","translation_en":"And it is not for a soul to believe except by permission of Allah, and He will place defilement upon those who will not use reason.","theme":"knowledge"},{"surahNumber":11,"ayahNumber":51,"surahName":"Hud","arabic":"يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ ۚ أَفَلَا تَعْقِلُونَ","translation_ar":"يقوم لآ أسٔلكم عليه أجرا  إن أجرى إلا على ٱلذى فطرنىٓ  أفلا تعقلون","translation_es":"¡Oh, pueblo mío! No les pido remuneración alguna a cambio [de trasmitirles el Mensaje], solo anhelo la recompensa de","translation_en":"O my people, I do not ask you for it any reward. My reward is only from the one who created me. Then will you not reason?","theme":"deeds"},{"surahNumber":17,"ayahNumber":35,"surahName":"Al-Israa","arabic":"وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًۭا","translation_ar":"وأوفوا ٱلكيل إذا كلتم وزنوا بٱلقسطاس ٱلمستقيم  ذلك خير وأحسن تأويلا","translation_es":"Midan y pesen con equidad. Esto es lo más conveniente y mejor para ustedes.","translation_en":"And give full measure when you measure, and weigh with an even balance. That is the best [way] and best in result.","theme":"light"},{"surahNumber":42,"ayahNumber":6,"surahName":"Ash-Shura","arabic":"وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍۢ","translation_ar":"وٱلذين ٱتخذوا من دونهٓ أوليآء ٱلله حفيظ عليهم ومآ أنت عليهم بوكيل","translation_es":"Quienes tomaron a otros [como divinidades y objeto de adoración] en lugar de Dios, deben saber que Dios tiene registradas","translation_en":"And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.","theme":"victory"},{"surahNumber":45,"ayahNumber":18,"surahName":"Al-Jaathiya","arabic":"ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍۢ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ","translation_ar":"ثم جعلنك على شريعة من ٱلأمر فٱتبعها ولا تتبع أهوآء ٱلذين لا يعلمون","translation_es":"A ti [¡oh, Mujámmad!] te he revelado una legislación para que la apliques y no sigas las pasiones de quienes no saben,","translation_en":"Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.","theme":"knowledge"}];

function getDailyVerse(){
  const today=new Date();
  const day=Math.floor((today-new Date(today.getFullYear(),0,0))/86400000);
  return DAILY_VERSES[day % DAILY_VERSES.length];
}
if (typeof window!=='undefined'){window.DAILY_VERSES=DAILY_VERSES;window.getDailyVerse=getDailyVerse;}
